import React, { useState } from 'react';
import {
  Box,
  Typography,
  Paper,
  TextField,
  Button,
  Alert,
  Grid,
  Chip,
} from '@mui/material';
import {
  Security,
  Description,
  Save,
} from '@mui/icons-material';

const CreateRole: React.FC = () => {
  const [formData, setFormData] = useState<{
    roleName: string;
    description: string;
    permissions: string[];
  }>({
    roleName: '',
    description: '',
    permissions: [],
  });
  const [success, setSuccess] = useState<string>('');
  const [error, setError] = useState<string>('');

  const availablePermissions = [
    'dashboard.view',
    'users.create',
    'users.read',
    'users.update',
    'users.delete',
    'mses.create',
    'mses.read',
    'mses.update',
    'mses.delete',
    'markets.create',
    'markets.read',
    'markets.update',
    'markets.delete',
    'reports.view',
    'reports.export',
    'system.admin',
  ];

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value,
    });
  };

  const handlePermissionToggle = (permission: string) => {
    setFormData(prev => ({
      ...prev,
      permissions: prev.permissions.includes(permission)
        ? prev.permissions.filter(p => p !== permission)
        : [...prev.permissions, permission],
    }));
  };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    if (!formData.roleName.trim()) {
      setError('Please enter a role name');
      return;
    }

    if (formData.permissions.length === 0) {
      setError('Please select at least one permission');
      return;
    }

    try {
      await new Promise(resolve => setTimeout(resolve, 1000));
      setSuccess('Role created successfully!');
      setFormData({
        roleName: '',
        description: '',
        permissions: [],
      });
    } catch (err) {
      setError('Failed to create role');
    }
  };

  return (
    <Box className="space-y-6">
      <Box className="flex justify-between items-center">
        <Typography variant="h5" className="font-semibold text-gray-800">
          Create New Role
        </Typography>
        <Button
          variant="contained"
          startIcon={<Security />}
          className="bg-blue-600 hover:bg-blue-700"
        >
          View All Roles
        </Button>
      </Box>

      {error && <Alert severity="error">{error}</Alert>}
      {success && <Alert severity="success">{success}</Alert>}

      <Grid container spacing={3}>
        {/* Form */}
        <Grid item xs={12} md={8}>
          <Paper className="p-6">
            <form onSubmit={handleSubmit}>
              <Grid container spacing={3}>
                <Grid item xs={12}>
                  <Box className="flex items-center space-x-2 mb-4">
                    <Security className="text-blue-600" />
                    <Typography variant="h6" className="font-semibold">
                      Role Information
                    </Typography>
                  </Box>
                </Grid>

                <Grid item xs={12} md={6}>
                  <TextField
                    fullWidth
                    label="Role Name"
                    name="roleName"
                    value={formData.roleName}
                    onChange={handleChange}
                    required
                    placeholder="e.g., Admin, Manager, Staff"
                    InputProps={{
                      startAdornment: <Security className="text-gray-400 mr-2" />,
                    }}
                  />
                </Grid>

                <Grid item xs={12}>
                  <TextField
                    fullWidth
                    label="Description"
                    name="description"
                    value={formData.description}
                    onChange={handleChange}
                    multiline
                    rows={3}
                    placeholder="Describe the role and its responsibilities..."
                    InputProps={{
                      startAdornment: <Description className="text-gray-400 mr-2" />,
                    }}
                  />
                </Grid>

                <Grid item xs={12}>
                  <Box className="flex items-center space-x-2 mb-4">
                    <Security className="text-green-600" />
                    <Typography variant="h6" className="font-semibold">
                      Permissions
                    </Typography>
                  </Box>
                  <Box className="flex flex-wrap gap-2">
                    {availablePermissions.map((permission) => (
                      <Chip
                        key={permission}
                        label={permission}
                        onClick={() => handlePermissionToggle(permission)}
                        className={
                          formData.permissions.includes(permission)
                            ? 'bg-blue-100 text-blue-800 hover:bg-blue-200'
                            : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
                        }
                        clickable
                      />
                    ))}
                  </Box>
                </Grid>

                <Grid item xs={12}>
                  <Box className="flex justify-end space-x-2 pt-4">
                    <Button
                      variant="outlined"
                      onClick={() => {
                        setFormData({
                          roleName: '',
                          description: '',
                          permissions: [],
                        });
                      }}
                    >
                      Clear Form
                    </Button>
                    <Button
                      type="submit"
                      variant="contained"
                      startIcon={<Save />}
                      className="bg-blue-600 hover:bg-blue-700"
                    >
                      Create Role
                    </Button>
                  </Box>
                </Grid>
              </Grid>
            </form>
          </Paper>
        </Grid>

        {/* Preview */}
        <Grid item xs={12} md={4}>
          <Paper className="p-6">
            <Typography variant="h6" className="font-semibold mb-4">
              Role Preview
            </Typography>
            
            <Box className="space-y-4">
              <Box>
                <Typography variant="body2" color="textSecondary">
                  Role Name
                </Typography>
                <Typography variant="body1" className="font-medium">
                  {formData.roleName || 'Not specified'}
                </Typography>
              </Box>

              <Box>
                <Typography variant="body2" color="textSecondary">
                  Description
                </Typography>
                <Typography variant="body1">
                  {formData.description || 'No description provided'}
                </Typography>
              </Box>

              <Box>
                <Typography variant="body2" color="textSecondary">
                  Selected Permissions ({formData.permissions.length})
                </Typography>
                <Box className="flex flex-wrap gap-1 mt-2">
                  {formData.permissions.map((permission) => (
                    <Chip
                      key={permission}
                      label={permission}
                      size="small"
                      className="bg-green-100 text-green-800"
                    />
                  ))}
                </Box>
              </Box>
            </Box>
          </Paper>
        </Grid>
      </Grid>
    </Box>
  );
};

export default CreateRole; 
