import React, { useState } from 'react';
import {
  Box,
  Typography,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  IconButton,
  Chip,
  TextField,
  InputAdornment,
  Button,
} from '@mui/material';
import {
  Search,
  Edit,
  Delete,
  Add,
} from '@mui/icons-material';

const ListMSECategory: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState<string>('');
  const [filterType, setFilterType] = useState<string>('');

  // Mock data for MSE categories
  const categories = [
    {
      id: 1,
      name: 'Agricultural Inputs',
      code: 'INPUT-1234',
      type: 'Input MSE',
      description: 'Suppliers of agricultural inputs like seeds, fertilizers, and tools',
      status: 'Active',
      mseCount: 45,
    },
    {
      id: 2,
      name: 'Food Processing',
      code: 'PROD-5678',
      type: 'Production MSE',
      description: 'Food processing and manufacturing businesses',
      status: 'Active',
      mseCount: 32,
    },
    {
      id: 3,
      name: 'Retail Distribution',
      code: 'OUTPUT-9012',
      type: 'Output MSE',
      description: 'Retail and distribution businesses',
      status: 'Active',
      mseCount: 28,
    },
  ];

  const filteredCategories = categories.filter(category => {
    const matchesSearch = category.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         category.description.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesType = !filterType || category.type === filterType;
    return matchesSearch && matchesType;
  });

  const types = Array.from(new Set(categories.map(c => c.type)));

  return (
    <Box className="space-y-6">
      <Box className="flex justify-between items-center">
        <Typography variant="h5" className="font-semibold text-gray-800">
          MSE Categories
        </Typography>
        <Button
          variant="contained"
          startIcon={<Add />}
          className="bg-blue-600 hover:bg-blue-700"
        >
          Add Category
        </Button>
      </Box>

      <Paper className="p-6">
        {/* Filters */}
        <Box className="flex gap-4 mb-6">
          <TextField
            placeholder="Search categories..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <Search />
                </InputAdornment>
              ),
            }}
            className="flex-1"
          />
          <TextField
            select
            label="Filter by Type"
            value={filterType}
            onChange={(e) => setFilterType(e.target.value)}
            className="w-48"
          >
            <option value="">All Types</option>
            {types.map((type) => (
              <option key={type} value={type}>
                {type}
              </option>
            ))}
          </TextField>
        </Box>

        {/* Table */}
        <TableContainer>
          <Table>
            <TableHead>
              <TableRow className="bg-gray-50">
                <TableCell className="font-semibold">Category Name</TableCell>
                <TableCell className="font-semibold">Code</TableCell>
                <TableCell className="font-semibold">Type</TableCell>
                <TableCell className="font-semibold">Description</TableCell>
                <TableCell className="font-semibold">MSEs</TableCell>
                <TableCell className="font-semibold">Status</TableCell>
                <TableCell className="font-semibold">Actions</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {filteredCategories.map((category) => (
                <TableRow key={category.id} className="hover:bg-gray-50">
                  <TableCell>
                    <Typography variant="subtitle2" className="font-medium">
                      {category.name}
                    </Typography>
                  </TableCell>
                  <TableCell>
                    <Typography variant="body2" className="font-mono">
                      {category.code}
                    </Typography>
                  </TableCell>
                  <TableCell>
                    <Chip
                      label={category.type}
                      size="small"
                      className="bg-blue-100 text-blue-800"
                    />
                  </TableCell>
                  <TableCell>
                    <Typography variant="body2" className="max-w-xs truncate">
                      {category.description}
                    </Typography>
                  </TableCell>
                  <TableCell>
                    <Chip
                      label={category.mseCount}
                      size="small"
                      className="bg-green-100 text-green-800"
                    />
                  </TableCell>
                  <TableCell>
                    <Chip
                      label={category.status}
                      size="small"
                      className={
                        category.status === 'Active'
                          ? 'bg-green-100 text-green-800'
                          : 'bg-red-100 text-red-800'
                      }
                    />
                  </TableCell>
                  <TableCell>
                    <Box className="flex space-x-1">
                      <IconButton size="small" className="text-blue-600">
                        <Edit fontSize="small" />
                      </IconButton>
                      <IconButton size="small" className="text-red-600">
                        <Delete fontSize="small" />
                      </IconButton>
                    </Box>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>

        {filteredCategories.length === 0 && (
          <Box className="text-center py-8">
            <Typography variant="body1" color="textSecondary">
              No categories found matching your criteria
            </Typography>
          </Box>
        )}
      </Paper>
    </Box>
  );
};

export default ListMSECategory; 
