import React, { useState } from 'react';
import {
  Box,
  Typography,
  Paper,
  Card,
  CardContent,
  Grid,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Chip,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Alert,
} from '@mui/material';
import {
  AccountBalance,
  Add,
  TrendingUp,
  TrendingDown,
  Visibility,
} from '@mui/icons-material';
import { WalletData } from '../../types';
import { api } from '../../config/api';
import { useAuth } from '../../context/AuthContext';

const MSEWallet: React.FC = () => {
  const { user } = useAuth();
  const [openDialog, setOpenDialog] = useState<boolean>(false);
  const [success, setSuccess] = useState<string>('');
  const [error, setError] = useState<string>('');
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  const [loading, setLoading] = useState<boolean>(false);

  // Wallet data state
  const [walletData, setWalletData] = useState<WalletData>({
    balance: '$12,450.00',
    currency: 'USD',
    status: 'Active',
    lastTransaction: '2024-01-15',
    transactions: [
      {
        id: 1,
        type: 'Credit',
        amount: '$5,000.00',
        description: 'Payment received from ABC Farm',
        date: '2024-01-15',
        status: 'Completed',
      },
      {
        id: 2,
        type: 'Debit',
        amount: '-$2,500.00',
        description: 'Payment to Green Supplies Co.',
        date: '2024-01-14',
        status: 'Completed',
      },
      {
        id: 3,
        type: 'Credit',
        amount: '$3,200.00',
        description: 'Payment received from XYZ Production',
        date: '2024-01-13',
        status: 'Completed',
      },
      {
        id: 4,
        type: 'Debit',
        amount: '-$1,800.00',
        description: 'Payment to Farm Tools Ltd',
        date: '2024-01-12',
        status: 'Completed',
      },
    ],
  });

  const handleOpenDialog = (): void => {
    setOpenDialog(true);
  };

  const handleCloseDialog = (): void => {
    setOpenDialog(false);
  };

  // Fetch wallet data on component mount
  React.useEffect(() => {
    const fetchWalletData = async () => {
      if (!user?.mseCode) return;
      
      try {
        setLoading(true);
        const response = await api.mses.getWallets(user.mseCode);
        
        if (response.success && response.data) {
          setWalletData(response.data);
        }
      } catch (err) {
        console.error('Failed to fetch wallet data:', err);
        setError('Failed to load wallet data');
      } finally {
        setLoading(false);
      }
    };

    fetchWalletData();
  }, [user?.mseCode]);

  const handleAddFunds = async (): Promise<void> => {
    setError('');
    setSuccess('');

    try {
      // TODO: Implement add funds API call
      // const response = await api.mses.addFunds(user?.mseCode, amount, description);
      
      // For now, simulate the API call
      await new Promise(resolve => setTimeout(resolve, 1000));
      setSuccess('Funds added successfully!');
      handleCloseDialog();
      
      // Refresh wallet data
      if (user?.mseCode) {
        const response = await api.mses.getWallets(user.mseCode);
        if (response.success && response.data) {
          setWalletData(response.data);
        }
      }
    } catch (err) {
      setError('Failed to add funds. Please try again.');
    }
  };

  return (
    <Box className="space-y-6">
      {/* Header */}
      <Box className="flex justify-between items-center">
        <Box>
          <Typography variant="h4" className="font-bold text-gray-800">
            My Wallet
          </Typography>
          <Typography variant="body1" color="textSecondary">
            Manage your wallet and view transaction history
          </Typography>
        </Box>
        <Button
          variant="contained"
          startIcon={<Add />}
          onClick={handleOpenDialog}
          className="bg-blue-600 hover:bg-blue-700"
        >
          Add Funds
        </Button>
      </Box>

      {error && <Alert severity="error">{error}</Alert>}
      {success && <Alert severity="success">{success}</Alert>}

      {/* Wallet Overview Cards */}
      <Grid container spacing={3}>
        <Grid item xs={12} sm={6} md={3}>
          <Card className="h-full hover:shadow-lg transition-shadow">
            <CardContent>
              <Box className="flex items-center justify-between">
                <Box>
                  <Typography color="textSecondary" gutterBottom>
                    Current Balance
                  </Typography>
                  <Typography variant="h4" className="font-bold text-green-600">
                    {walletData.balance}
                  </Typography>
                </Box>
                <Box className="p-2 bg-green-100 rounded-lg">
                  <AccountBalance className="text-green-600" />
                </Box>
              </Box>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Card className="h-full hover:shadow-lg transition-shadow">
            <CardContent>
              <Box className="flex items-center justify-between">
                <Box>
                  <Typography color="textSecondary" gutterBottom>
                    Currency
                  </Typography>
                  <Typography variant="h6" className="font-bold">
                    {walletData.currency}
                  </Typography>
                </Box>
                <Box className="p-2 bg-blue-100 rounded-lg">
                  <TrendingUp className="text-blue-600" />
                </Box>
              </Box>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Card className="h-full hover:shadow-lg transition-shadow">
            <CardContent>
              <Box className="flex items-center justify-between">
                <Box>
                  <Typography color="textSecondary" gutterBottom>
                    Status
                  </Typography>
                  <Chip
                    label={walletData.status}
                    size="small"
                    className="bg-green-100 text-green-800"
                  />
                </Box>
                <Box className="p-2 bg-purple-100 rounded-lg">
                  <Visibility className="text-purple-600" />
                </Box>
              </Box>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Card className="h-full hover:shadow-lg transition-shadow">
            <CardContent>
              <Box className="flex items-center justify-between">
                <Box>
                  <Typography color="textSecondary" gutterBottom>
                    Last Transaction
                  </Typography>
                  <Typography variant="h6" className="font-bold">
                    {walletData.lastTransaction}
                  </Typography>
                </Box>
                <Box className="p-2 bg-orange-100 rounded-lg">
                  <TrendingDown className="text-orange-600" />
                </Box>
              </Box>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Transaction History */}
      <Paper className="p-6">
        <Typography variant="h6" className="font-semibold mb-4">
          Recent Transactions
        </Typography>
        <TableContainer>
          <Table>
            <TableHead>
              <TableRow className="bg-gray-50">
                <TableCell className="font-semibold">Type</TableCell>
                <TableCell className="font-semibold">Amount</TableCell>
                <TableCell className="font-semibold">Description</TableCell>
                <TableCell className="font-semibold">Date</TableCell>
                <TableCell className="font-semibold">Status</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {walletData.transactions.map((transaction) => (
                <TableRow key={transaction.id} className="hover:bg-gray-50">
                  <TableCell>
                    <Chip
                      label={transaction.type}
                      size="small"
                      className={
                        transaction.type === 'Credit'
                          ? 'bg-green-100 text-green-800'
                          : 'bg-red-100 text-red-800'
                      }
                    />
                  </TableCell>
                  <TableCell>
                    <Typography
                      variant="body2"
                      className={`font-medium ${
                        transaction.type === 'Credit'
                          ? 'text-green-600'
                          : 'text-red-600'
                      }`}
                    >
                      {transaction.amount}
                    </Typography>
                  </TableCell>
                  <TableCell>
                    <Typography variant="body2">{transaction.description}</Typography>
                  </TableCell>
                  <TableCell>
                    <Typography variant="body2">{transaction.date}</Typography>
                  </TableCell>
                  <TableCell>
                    <Chip
                      label={transaction.status}
                      size="small"
                      className="bg-blue-100 text-blue-800"
                    />
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      </Paper>

      {/* Add Funds Dialog */}
      <Dialog open={openDialog} onClose={handleCloseDialog} maxWidth="sm" fullWidth>
        <DialogTitle>Add Funds to Wallet</DialogTitle>
        <DialogContent>
          <Box className="space-y-4 pt-2">
            <TextField
              fullWidth
              label="Amount"
              type="number"
              placeholder="Enter amount to add"
              InputProps={{
                startAdornment: <Typography variant="body2">$</Typography>,
              }}
            />
            <TextField
              fullWidth
              label="Description (Optional)"
              placeholder="Reason for adding funds"
              multiline
              rows={3}
            />
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseDialog}>Cancel</Button>
          <Button
            onClick={handleAddFunds}
            variant="contained"
            className="bg-blue-600 hover:bg-blue-700"
          >
            Add Funds
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default MSEWallet; 