// Helper function to build full API URL
export const buildApiUrl = (endpoint: string, params: Record<string, string> = {}): string => {
  let url = `${API_CONFIG.BASE_URL}${endpoint}`;
  
  // Replace URL parameters
  Object.keys(params).forEach(key => {
    url = url.replace(`:${key}`, params[key]);
  });
  
  return url;
};

// Helper function to get auth headers
export const getAuthHeaders = (): Record<string, string> => {
  const token = localStorage.getItem('accessToken');
  return {
    ...API_CONFIG.HEADERS,
    ...(token && { Authorization: `Bearer ${token}` }),
  };
};

// Token refresh function
export const refreshToken = async (): Promise<boolean> => {
  const refreshTokenValue = localStorage.getItem('refreshToken');
  if (!refreshTokenValue) {
    return false;
  }

  try {
    const response = await fetch(`${API_CONFIG.BASE_URL}${API_CONFIG.ENDPOINTS.AUTH.REFRESH}`, {
      method: API_CONFIG.METHODS.POST,
      headers: API_CONFIG.HEADERS,
      body: JSON.stringify({ refresh: refreshTokenValue }),
    });

    if (response.ok) {
      const data = await response.json();
      if (data.access) {
        localStorage.setItem('accessToken', data.access);
        return true;
      }
    }
  } catch (error) {
    console.error('Token refresh failed:', error);
  }

  // If refresh fails, clear all tokens
  localStorage.removeItem('accessToken');
  localStorage.removeItem('refreshToken');
  return false;
};

// API Response handler
export const handleApiResponse = async <T>(response: Response): Promise<T> => {
  if (response.status === 401) {
    // Try to refresh token
    const refreshSuccess = await refreshToken();
    if (!refreshSuccess) {
      // Redirect to login if refresh fails
      window.location.href = '/login';
      throw new Error('Authentication required. Please log in again.');
    }
    throw new Error('Token refreshed. Please retry the request.');
  }
  
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    throw new Error(errorData.message || `HTTP error! status: ${response.status}`);
  }
  
  return response.json();
};

// API Request wrapper with retry logic for token refresh
export const apiRequest = async <T>(
  endpoint: string, 
  options: {
    method?: string;
    body?: any;
    params?: Record<string, string>;
    headers?: Record<string, string>;
    timeout?: number;
    retryCount?: number;
  } = {}
): Promise<T> => {
  const {
    method = API_CONFIG.METHODS.GET,
    body,
    params = {},
    headers = {},
    timeout = API_CONFIG.TIMEOUT,
    retryCount = 0,
  } = options;
  
  const url = buildApiUrl(endpoint, params);
  const requestHeaders = {
    ...getAuthHeaders(),
    ...headers,
  };
  
  const config: RequestInit = {
    method,
    headers: requestHeaders,
    ...(body && { body: JSON.stringify(body) }),
  };
  
  // Add timeout
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), timeout);
  
  try {
    const response = await fetch(url, {
      ...config,
      signal: controller.signal,
    });
    
    clearTimeout(timeoutId);
    
    // If we get a 401 and haven't retried yet, try to refresh token and retry
    if (response.status === 401 && retryCount === 0) {
      const refreshSuccess = await refreshToken();
      if (refreshSuccess) {
        // Retry the request with new token
        return apiRequest<T>(endpoint, { ...options, retryCount: retryCount + 1 });
      }
    }
    
    return await handleApiResponse<T>(response);
  } catch (error) {
    clearTimeout(timeoutId);
    if (error instanceof Error && error.name === 'AbortError') {
      throw new Error('Request timeout');
    }
    throw error;
  }
};

