import React, { useState } from 'react';
import {
  Box,
  Typography,
  Paper,
  TextField,
  Button,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Alert,
  Grid,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  IconButton,
  Chip,
} from '@mui/material';
import {
  VpnKey,
  Person,
  Visibility,
  VisibilityOff,
  Edit,
  Delete,
  Refresh,
} from '@mui/icons-material';

const CreateCredentials: React.FC = () => {
  const [formData, setFormData] = useState<{
    staffMember: string;
    username: string;
    password: string;
    confirmPassword: string;
    role: string;
  }>({
    staffMember: '',
    username: '',
    password: '',
    confirmPassword: '',
    role: '',
  });
  const [showPassword, setShowPassword] = useState<boolean>(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState<boolean>(false);
  const [success, setSuccess] = useState<string>('');
  const [error, setError] = useState<string>('');

  // Mock data
  const staffMembers = [
    { id: 1, name: 'John Smith', email: 'john.smith@company.com', department: 'IT' },
    { id: 2, name: 'Jane Doe', email: 'jane.doe@company.com', department: 'Finance' },
    { id: 3, name: 'Mike Johnson', email: 'mike.johnson@company.com', department: 'Operations' },
  ];

  const roles = [
    'Admin',
    'Manager',
    'Staff',
    'Viewer',
  ];

  const existingCredentials = [
    {
      id: 1,
      staffName: 'John Smith',
      username: 'john.smith',
      role: 'Admin',
      status: 'Active',
      lastLogin: '2024-01-15 10:30',
    },
    {
      id: 2,
      staffName: 'Jane Doe',
      username: 'jane.doe',
      role: 'Manager',
      status: 'Active',
      lastLogin: '2024-01-14 15:45',
    },
  ];

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement> | any) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value,
    });
  };

  const generatePassword = () => {
    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%^&*';
    let password = '';
    for (let i = 0; i < 12; i++) {
      password += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    setFormData(prev => ({
      ...prev,
      password: password,
      confirmPassword: password,
    }));
  };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    if (!formData.staffMember || !formData.username || !formData.password || !formData.role) {
      setError('Please fill in all required fields');
      return;
    }

    if (formData.password !== formData.confirmPassword) {
      setError('Passwords do not match');
      return;
    }

    if (formData.password.length < 8) {
      setError('Password must be at least 8 characters long');
      return;
    }

    try {
      await new Promise(resolve => setTimeout(resolve, 1000));
      setSuccess('Login credentials created successfully!');
      setFormData({
        staffMember: '',
        username: '',
        password: '',
        confirmPassword: '',
        role: '',
      });
    } catch (err) {
      setError('Failed to create credentials');
    }
  };

  const handleDelete = (credentialId: any) => {
    if (window.confirm('Are you sure you want to delete these credentials?')) {
      console.log('Delete credential:', credentialId);
      // Implement delete functionality
    }
  };

  return (
    <Box className="space-y-6">
      <Box className="flex justify-between items-center">
        <Typography variant="h5" className="font-semibold text-gray-800">
          Create Staff Login Credentials
        </Typography>
        <Button
          variant="contained"
          startIcon={<VpnKey />}
          className="bg-blue-600 hover:bg-blue-700"
        >
          View All Credentials
        </Button>
      </Box>

      {error && <Alert severity="error">{error}</Alert>}
      {success && <Alert severity="success">{success}</Alert>}

      <Grid container spacing={3}>
        {/* Create Credentials Form */}
        <Grid item xs={12} md={6}>
          <Paper className="p-6">
            <Box className="flex items-center space-x-2 mb-4">
              <VpnKey className="text-blue-600" />
              <Typography variant="h6" className="font-semibold">
                Create New Credentials
              </Typography>
            </Box>

            <form onSubmit={handleSubmit}>
              <Grid container spacing={3}>
                <Grid item xs={12}>
                  <FormControl fullWidth required>
                    <InputLabel>Select Staff Member</InputLabel>
                    <Select
                      name="staffMember"
                      value={formData.staffMember}
                      onChange={handleChange}
                      label="Select Staff Member"
                    >
                      {staffMembers.map((staff) => (
                        <MenuItem key={staff.id} value={staff.id}>
                          {staff.name} - {staff.department}
                        </MenuItem>
                      ))}
                    </Select>
                  </FormControl>
                </Grid>

                <Grid item xs={12}>
                  <TextField
                    fullWidth
                    label="Username"
                    name="username"
                    value={formData.username}
                    onChange={handleChange}
                    required
                    placeholder="e.g., john.smith"
                    InputProps={{
                      startAdornment: <Person className="text-gray-400 mr-2" />,
                    }}
                  />
                </Grid>

                <Grid item xs={12}>
                  <TextField
                    fullWidth
                    label="Password"
                    name="password"
                    type={showPassword ? 'text' : 'password'}
                    value={formData.password}
                    onChange={handleChange}
                    required
                    InputProps={{
                      startAdornment: <VpnKey className="text-gray-400 mr-2" />,
                      endAdornment: (
                        <IconButton
                          onClick={() => setShowPassword(!showPassword)}
                          edge="end"
                        >
                          {showPassword ? <VisibilityOff /> : <Visibility />}
                        </IconButton>
                      ),
                    }}
                  />
                </Grid>

                <Grid item xs={12}>
                  <TextField
                    fullWidth
                    label="Confirm Password"
                    name="confirmPassword"
                    type={showConfirmPassword ? 'text' : 'password'}
                    value={formData.confirmPassword}
                    onChange={handleChange}
                    required
                    InputProps={{
                      startAdornment: <VpnKey className="text-gray-400 mr-2" />,
                      endAdornment: (
                        <IconButton
                          onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                          edge="end"
                        >
                          {showConfirmPassword ? <VisibilityOff /> : <Visibility />}
                        </IconButton>
                      ),
                    }}
                  />
                </Grid>

                <Grid item xs={12}>
                  <FormControl fullWidth required>
                    <InputLabel>Role</InputLabel>
                    <Select
                      name="role"
                      value={formData.role}
                      onChange={handleChange}
                      label="Role"
                    >
                      {roles.map((role) => (
                        <MenuItem key={role} value={role}>
                          {role}
                        </MenuItem>
                      ))}
                    </Select>
                  </FormControl>
                </Grid>

                <Grid item xs={12}>
                  <Box className="flex space-x-2">
                    <Button
                      variant="outlined"
                      startIcon={<Refresh />}
                      onClick={generatePassword}
                      className="flex-1"
                    >
                      Generate Password
                    </Button>
                    <Button
                      type="submit"
                      variant="contained"
                      className="bg-blue-600 hover:bg-blue-700 flex-1"
                    >
                      Create Credentials
                    </Button>
                  </Box>
                </Grid>
              </Grid>
            </form>
          </Paper>
        </Grid>

        {/* Existing Credentials */}
        <Grid item xs={12} md={6}>
          <Paper className="p-6">
            <Typography variant="h6" className="font-semibold mb-4">
              Existing Credentials
            </Typography>
            
            <TableContainer>
              <Table>
                <TableHead>
                  <TableRow className="bg-gray-50">
                    <TableCell className="font-semibold">Staff Name</TableCell>
                    <TableCell className="font-semibold">Username</TableCell>
                    <TableCell className="font-semibold">Role</TableCell>
                    <TableCell className="font-semibold">Status</TableCell>
                    <TableCell className="font-semibold">Actions</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {existingCredentials.map((credential) => (
                    <TableRow key={credential.id} className="hover:bg-gray-50">
                      <TableCell>
                        <Typography variant="body2">{credential.staffName}</Typography>
                      </TableCell>
                      <TableCell>
                        <Typography variant="body2" className="font-mono">
                          {credential.username}
                        </Typography>
                      </TableCell>
                      <TableCell>
                        <Chip
                          label={credential.role}
                          size="small"
                          className="bg-blue-100 text-blue-800"
                        />
                      </TableCell>
                      <TableCell>
                        <Chip
                          label={credential.status}
                          size="small"
                          className={
                            credential.status === 'Active'
                              ? 'bg-green-100 text-green-800'
                              : 'bg-red-100 text-red-800'
                          }
                        />
                      </TableCell>
                      <TableCell>
                        <Box className="flex space-x-1">
                          <IconButton 
                            size="small" 
                            className="text-green-600"
                          >
                            <Edit fontSize="small" />
                          </IconButton>
                          <IconButton 
                            size="small" 
                            className="text-red-600"
                            onClick={() => handleDelete(credential.id)}
                          >
                            <Delete fontSize="small" />
                          </IconButton>
                        </Box>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          </Paper>
        </Grid>
      </Grid>
    </Box>
  );
};

export default CreateCredentials; 
