import React, { useState } from 'react';
import {
  Box,
  Typography,
  Paper,
  TextField,
  Button,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Alert,
  Grid,
  Divider,
} from '@mui/material';
import {
  Category,
  Description,
  Code,
  Save,
} from '@mui/icons-material';

const RegisterMSECategory: React.FC = () => {
  const [formData, setFormData] = useState<any>({
    categoryName: '',
    description: '',
    type: '',
    code: '',
  });
  const [success, setSuccess] = useState<string>('');
  const [error, setError] = useState<string>('');

  const types = [
    'Input MSE',
    'Production MSE',
    'Output MSE',
  ];

  const handleChange = (e: any) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value,
    });

    // Auto-generate code when category name changes
    if (name === 'categoryName') {
      const code = value
        .toUpperCase()
        .replace(/[^A-Z0-9]/g, '')
        .substring(0, 6);
      setFormData((prev: any) => ({
        ...prev,
        [name]: value,
        code: code,
      }));
    }
  };

  const handleSubmit = async (e: any) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    if (!formData.categoryName || !formData.type) {
      setError('Please fill in all required fields');
      return;
    }

    try {
      await new Promise(resolve => setTimeout(resolve, 1000));
      setSuccess('MSE Category registered successfully!');
      setFormData({
        categoryName: '',
        description: '',
        type: '',
        code: '',
      });
    } catch (err) {
      setError('Failed to register MSE Category');
    }
  };

  return (
    <Box className="space-y-6">
      <Box className="flex justify-between items-center">
        <Typography variant="h5" className="font-semibold text-gray-800">
          Register MSE Category
        </Typography>
        <Button
          variant="contained"
          startIcon={<Category />}
          className="bg-blue-600 hover:bg-blue-700"
        >
          View Categories
        </Button>
      </Box>

      {error && <Alert severity="error">{error}</Alert>}
      {success && <Alert severity="success">{success}</Alert>}

      <Grid container spacing={3}>
        {/* Form */}
        <Grid item xs={12} md={8}>
          <Paper className="p-6">
            <form onSubmit={handleSubmit}>
              <Grid container spacing={3}>
                <Grid item xs={12}>
                  <Box className="flex items-center space-x-2 mb-4">
                    <Category className="text-blue-600" />
                    <Typography variant="h6" className="font-semibold">
                      Category Information
                    </Typography>
                  </Box>
                </Grid>

                <Grid item xs={12} md={6}>
                  <TextField
                    fullWidth
                    label="Category Name"
                    name="categoryName"
                    value={formData.categoryName}
                    onChange={handleChange}
                    required
                    placeholder="e.g., Agricultural Inputs"
                    InputProps={{
                      startAdornment: <Category className="text-gray-400 mr-2" />,
                    }}
                  />
                </Grid>

                <Grid item xs={12} md={6}>
                  <FormControl fullWidth required>
                    <InputLabel>Category Type</InputLabel>
                    <Select
                      name="type"
                      value={formData.type}
                      onChange={handleChange}
                      label="Category Type"
                    >
                      {types.map((type) => (
                        <MenuItem key={type} value={type}>
                          {type}
                        </MenuItem>
                      ))}
                    </Select>
                  </FormControl>
                </Grid>

                <Grid item xs={12} md={6}>
                  <TextField
                    fullWidth
                    label="Category Code"
                    name="code"
                    value={formData.code}
                    onChange={handleChange}
                    placeholder="Auto-generated"
                    InputProps={{
                      startAdornment: <Code className="text-gray-400 mr-2" />,
                      readOnly: true,
                    }}
                  />
                </Grid>

                <Grid item xs={12}>
                  <TextField
                    fullWidth
                    label="Description"
                    name="description"
                    value={formData.description}
                    onChange={handleChange}
                    multiline
                    rows={4}
                    placeholder="Describe the category, its purpose, and what types of businesses it includes..."
                    InputProps={{
                      startAdornment: <Description className="text-gray-400 mr-2" />,
                    }}
                  />
                </Grid>

                <Grid item xs={12}>
                  <Box className="flex justify-end space-x-2 pt-4">
                    <Button
                      variant="outlined"
                      onClick={() => {
                        setFormData({
                          categoryName: '',
                          description: '',
                          type: '',
                          code: '',
                        });
                      }}
                    >
                      Clear Form
                    </Button>
                    <Button
                      type="submit"
                      variant="contained"
                      startIcon={<Save />}
                      className="bg-blue-600 hover:bg-blue-700"
                    >
                      Register Category
                    </Button>
                  </Box>
                </Grid>
              </Grid>
            </form>
          </Paper>
        </Grid>

        {/* Preview */}
        <Grid item xs={12} md={4}>
          <Paper className="p-6">
            <Typography variant="h6" className="font-semibold mb-4">
              Category Preview
            </Typography>
            <Divider className="mb-4" />
            
            <Box className="space-y-4">
              <Box>
                <Typography variant="body2" color="textSecondary">
                  Category Name
                </Typography>
                <Typography variant="body1" className="font-medium">
                  {formData.categoryName || 'Not specified'}
                </Typography>
              </Box>

              <Box>
                <Typography variant="body2" color="textSecondary">
                  Category Type
                </Typography>
                <Typography variant="body1" className="font-medium">
                  {formData.type || 'Not specified'}
                </Typography>
              </Box>

              <Box>
                <Typography variant="body2" color="textSecondary">
                  Category Code
                </Typography>
                <Typography variant="body1" className="font-medium">
                  {formData.code || 'Not generated'}
                </Typography>
              </Box>

              <Box>
                <Typography variant="body2" color="textSecondary">
                  Description
                </Typography>
                <Typography variant="body1">
                  {formData.description || 'No description provided'}
                </Typography>
              </Box>
            </Box>
          </Paper>
        </Grid>
      </Grid>
    </Box>
  );
};

export default RegisterMSECategory; 
