import React, { useState } from 'react';
import {
  Box,
  Typography,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  IconButton,
  Chip,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Alert,
  Grid,
} from '@mui/material';
import {
  Add,
  AccountBalance,
  Visibility,
  Edit,
  Delete,
} from '@mui/icons-material';

const ManageWallet: React.FC = () => {
  const [openDialog, setOpenDialog] = useState<boolean>(false);
  const [editingWallet, setEditingWallet] = useState<any>(null);
  const [success, setSuccess] = useState<string>('');
  const [error, setError] = useState<string>('');

  // Mock data
  const wallets = [
    {
      id: 1,
      mseName: 'ABC Farm',
      mseCode: 'MSE001',
      type: 'Business',
      balance: '$12,450.00',
      currency: 'USD',
      status: 'Active',
      lastTransaction: '2024-01-15',
      description: 'Main business account',
    },
    {
      id: 2,
      mseName: 'XYZ Production',
      mseCode: 'MSE002',
      type: 'Savings',
      balance: '$8,750.00',
      currency: 'USD',
      status: 'Active',
      lastTransaction: '2024-01-14',
      description: 'Savings account for expansion',
    },
    {
      id: 3,
      mseName: 'DEF Trading',
      mseCode: 'MSE003',
      type: 'Business',
      balance: '$5,200.00',
      currency: 'USD',
      status: 'Inactive',
      lastTransaction: '2024-01-10',
      description: 'Trading operations account',
    },
  ];

  const mseOptions = [
    { id: 1, name: 'ABC Farm', code: 'MSE001' },
    { id: 2, name: 'XYZ Production', code: 'MSE002' },
    { id: 3, name: 'DEF Trading', code: 'MSE003' },
    { id: 4, name: 'GHI Services', code: 'MSE004' },
  ];

  const walletTypes = ['Business', 'Savings', 'Investment', 'Emergency'];

  const currencies = ['USD', 'EUR', 'GBP', 'KES'];

  const handleOpenDialog = (wallet: any = null) => {
    setEditingWallet(wallet);
    setOpenDialog(true);
  };

  const handleCloseDialog = (): void => {
    setOpenDialog(false);
    setEditingWallet(null);
  };

  const handleSubmit = async () => {
    setError('');
    setSuccess('');

    try {
      await new Promise(resolve => setTimeout(resolve, 1000));
      setSuccess(editingWallet ? 'Wallet updated successfully!' : 'Wallet created successfully!');
      handleCloseDialog();
    } catch (err) {
      setError(editingWallet ? 'Failed to update wallet' : 'Failed to create wallet');
    }
  };

  const handleDelete = async (walletId: any) => {
    if (window.confirm('Are you sure you want to delete this wallet?')) {
      try {
        await new Promise(resolve => setTimeout(resolve, 1000));
        setSuccess('Wallet deleted successfully!');
      } catch (err) {
        setError('Failed to delete wallet');
      }
    }
  };

  return (
    <Box className="space-y-6">
      <Box className="flex justify-between items-center">
        <Typography variant="h5" className="font-semibold text-gray-800">
          Manage MSE Wallets
        </Typography>
        <Button
          variant="contained"
          startIcon={<Add />}
          onClick={() => handleOpenDialog()}
          className="bg-blue-600 hover:bg-blue-700"
        >
          Create Wallet
        </Button>
      </Box>

      {error && <Alert severity="error">{error}</Alert>}
      {success && <Alert severity="success">{success}</Alert>}

      {/* Wallet Statistics */}
      <Grid container spacing={3}>
        <Grid item xs={12} sm={6} md={3}>
          <Paper className="p-4 text-center hover:shadow-lg transition-shadow">
            <AccountBalance className="text-blue-600 text-3xl mb-2" />
            <Typography variant="h6">Total Wallets</Typography>
            <Typography variant="body2" color="textSecondary">
              {wallets.length} wallets
            </Typography>
          </Paper>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Paper className="p-4 text-center hover:shadow-lg transition-shadow">
            <AccountBalance className="text-green-600 text-3xl mb-2" />
            <Typography variant="h6">Active Wallets</Typography>
            <Typography variant="body2" color="textSecondary">
              {wallets.filter(w => w.status === 'Active').length} active
            </Typography>
          </Paper>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Paper className="p-4 text-center hover:shadow-lg transition-shadow">
            <AccountBalance className="text-purple-600 text-3xl mb-2" />
            <Typography variant="h6">Total Balance</Typography>
            <Typography variant="body2" color="textSecondary">
              $26,400.00
            </Typography>
          </Paper>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Paper className="p-4 text-center hover:shadow-lg transition-shadow">
            <AccountBalance className="text-orange-600 text-3xl mb-2" />
            <Typography variant="h6">This Month</Typography>
            <Typography variant="body2" color="textSecondary">
              +$2,450.00
            </Typography>
          </Paper>
        </Grid>
      </Grid>

      {/* Wallets Table */}
      <Paper className="p-6">
        <Typography variant="h6" className="font-semibold mb-4">
          All Wallets
        </Typography>
        <TableContainer>
          <Table>
            <TableHead>
              <TableRow className="bg-gray-50">
                <TableCell className="font-semibold">MSE Name</TableCell>
                <TableCell className="font-semibold">MSE Code</TableCell>
                <TableCell className="font-semibold">Wallet Type</TableCell>
                <TableCell className="font-semibold">Balance</TableCell>
                <TableCell className="font-semibold">Currency</TableCell>
                <TableCell className="font-semibold">Status</TableCell>
                <TableCell className="font-semibold">Last Transaction</TableCell>
                <TableCell className="font-semibold">Actions</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {wallets.map((wallet) => (
                <TableRow key={wallet.id} className="hover:bg-gray-50">
                  <TableCell>
                    <Box>
                      <Typography variant="subtitle2" className="font-medium">
                        {wallet.mseName}
                      </Typography>
                      <Typography variant="body2" color="textSecondary">
                        {wallet.description}
                      </Typography>
                    </Box>
                  </TableCell>
                  <TableCell>
                    <Typography variant="body2">{wallet.mseCode}</Typography>
                  </TableCell>
                  <TableCell>
                    <Chip
                      label={wallet.type}
                      size="small"
                      className="bg-blue-100 text-blue-800"
                    />
                  </TableCell>
                  <TableCell>
                    <Typography variant="body2" className="font-medium">
                      {wallet.balance}
                    </Typography>
                  </TableCell>
                  <TableCell>
                    <Typography variant="body2">{wallet.currency}</Typography>
                  </TableCell>
                  <TableCell>
                    <Chip
                      label={wallet.status}
                      size="small"
                      className={
                        wallet.status === 'Active'
                          ? 'bg-green-100 text-green-800'
                          : 'bg-red-100 text-red-800'
                      }
                    />
                  </TableCell>
                  <TableCell>
                    <Typography variant="body2">{wallet.lastTransaction}</Typography>
                  </TableCell>
                  <TableCell>
                    <Box className="flex space-x-1">
                      <IconButton 
                        size="small" 
                        className="text-blue-600"
                        onClick={() => handleOpenDialog(wallet)}
                      >
                        <Visibility fontSize="small" />
                      </IconButton>
                      <IconButton 
                        size="small" 
                        className="text-green-600"
                        onClick={() => handleOpenDialog(wallet)}
                      >
                        <Edit fontSize="small" />
                      </IconButton>
                      <IconButton 
                        size="small" 
                        className="text-red-600"
                        onClick={() => handleDelete(wallet.id)}
                      >
                        <Delete fontSize="small" />
                      </IconButton>
                    </Box>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      </Paper>

      {/* Create/Edit Wallet Dialog */}
      <Dialog open={openDialog} onClose={handleCloseDialog} maxWidth="md" fullWidth>
        <DialogTitle>
          {editingWallet ? 'Edit Wallet' : 'Create New Wallet'}
        </DialogTitle>
        <DialogContent>
          <Grid container spacing={2} className="pt-2">
            <Grid item xs={12} md={6}>
              <FormControl fullWidth>
                <InputLabel>MSE</InputLabel>
                <Select
                  label="MSE"
                  defaultValue={editingWallet?.mseCode || ''}
                >
                  {mseOptions.map((mse) => (
                    <MenuItem key={mse.id} value={mse.code}>
                      {mse.name} ({mse.code})
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} md={6}>
              <FormControl fullWidth>
                <InputLabel>Wallet Type</InputLabel>
                <Select
                  label="Wallet Type"
                  defaultValue={editingWallet?.type || ''}
                >
                  {walletTypes.map((type) => (
                    <MenuItem key={type} value={type}>
                      {type}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="Initial Balance"
                type="number"
                defaultValue={editingWallet?.balance?.replace('$', '').replace(',', '') || ''}
              />
            </Grid>
            <Grid item xs={12} md={6}>
              <FormControl fullWidth>
                <InputLabel>Currency</InputLabel>
                <Select
                  label="Currency"
                  defaultValue={editingWallet?.currency || 'USD'}
                >
                  {currencies.map((currency) => (
                    <MenuItem key={currency} value={currency}>
                      {currency}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Description"
                multiline
                rows={3}
                defaultValue={editingWallet?.description || ''}
              />
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseDialog}>Cancel</Button>
          <Button 
            onClick={handleSubmit} 
            variant="contained"
            className="bg-blue-600 hover:bg-blue-700"
          >
            {editingWallet ? 'Update' : 'Create'}
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default ManageWallet; 
