import React, { useState } from 'react';
import {
  Box,
  Typography,
  Paper,
  Card,
  CardContent,
  Grid,
  Button,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Chip,
  Dialog,
  DialogTitle,
  DialogContent,
  Alert,
} from '@mui/material';
import {
  Assessment,
  TrendingUp,
  Inventory,
  ShoppingCart,
  AttachMoney,
  Download,
  Lock,
  FilterList,
} from '@mui/icons-material';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';

const Reports: React.FC = () => {
  const [selectedMSE, setSelectedMSE] = useState<string>('');
  const [startDate, setStartDate] = useState<Date | null>(null);
  const [endDate, setEndDate] = useState<Date | null>(null);
  const [selectedReportType, setSelectedReportType] = useState<string>('');
  const [isPeriodLocked, setIsPeriodLocked] = useState<boolean>(false);
  const [openReportDialog, setOpenReportDialog] = useState<boolean>(false);
  const [currentReport, setCurrentReport] = useState<any>(null);

  // Mock MSE data
  const mseList = [
    { id: 1, name: 'ABC Farm', code: 'MSE001', type: 'Input MSE' },
    { id: 2, name: 'XYZ Production', code: 'MSE002', type: 'Production MSE' },
    { id: 3, name: 'DEF Trading', code: 'MSE003', type: 'Output MSE' },
    { id: 4, name: 'GHI Services', code: 'MSE004', type: 'Input MSE' },
  ];

  const reportTypes = [
    {
      id: 'income',
      title: 'Income Report',
      description: 'Sale - Purchase cost analysis',
      icon: <TrendingUp className="text-green-600" />,
      color: 'green',
    },
    {
      id: 'stock',
      title: 'Stock Balance Report',
      description: 'Quantity purchased, sold, and available',
      icon: <Inventory className="text-blue-600" />,
      color: 'blue',
    },
    {
      id: 'purchases',
      title: 'Purchases Report',
      description: 'Detailed purchase transactions',
      icon: <ShoppingCart className="text-red-600" />,
      color: 'red',
    },
    {
      id: 'sales',
      title: 'Sales Report',
      description: 'Detailed sales transactions',
      icon: <AttachMoney className="text-purple-600" />,
      color: 'purple',
    },
  ];

  // Mock report data
  const generateMockReportData = (reportType: string, mseId: string, startDate: Date, endDate: Date) => {
    const mse = mseList.find(m => m.id === parseInt(mseId));
    
    switch (reportType) {
      case 'income':
        return {
          title: 'Income Report',
          mse: mse?.name || 'Unknown MSE',
          period: `${startDate} to ${endDate}`,
          summary: {
            totalSales: 125000,
            totalPurchases: 85000,
            grossProfit: 40000,
            netProfit: 32000,
            profitMargin: 25.6,
          },
          details: [
            { date: '2024-01-15', item: 'Organic Seeds', sales: 25000, purchases: 15000, profit: 10000 },
            { date: '2024-01-14', item: 'NPK Fertilizer', sales: 30000, purchases: 22000, profit: 8000 },
            { date: '2024-01-13', item: 'Garden Tools', sales: 20000, purchases: 12000, profit: 8000 },
            { date: '2024-01-12', item: 'Pesticides', sales: 15000, purchases: 10000, profit: 5000 },
            { date: '2024-01-11', item: 'Irrigation Systems', sales: 35000, purchases: 26000, profit: 9000 },
          ]
        };

      case 'stock':
        return {
          title: 'Stock Balance Report',
          mse: mse?.name || 'Unknown MSE',
          period: `${startDate} to ${endDate}`,
          summary: {
            totalItems: 25,
            totalPurchased: 1500,
            totalSold: 1200,
            totalAvailable: 300,
            lowStockItems: 3,
          },
          details: [
            { item: 'Organic Seeds', purchased: 500, sold: 420, available: 80, status: 'In Stock' },
            { item: 'NPK Fertilizer', purchased: 300, sold: 280, available: 20, status: 'Low Stock' },
            { item: 'Garden Tools', purchased: 200, sold: 180, available: 20, status: 'Low Stock' },
            { item: 'Pesticides', purchased: 150, sold: 120, available: 30, status: 'In Stock' },
            { item: 'Irrigation Systems', purchased: 100, sold: 80, available: 20, status: 'Low Stock' },
          ]
        };

      case 'purchases':
        return {
          title: 'Purchases Report',
          mse: mse?.name || 'Unknown MSE',
          period: `${startDate} to ${endDate}`,
          summary: {
            totalPurchases: 45,
            totalAmount: 85000,
            averagePurchase: 1889,
            topSupplier: 'Green Supplies Co.',
          },
          details: [
            { date: '2024-01-15', supplier: 'Green Supplies Co.', item: 'Organic Seeds', quantity: 100, amount: 15000 },
            { date: '2024-01-14', supplier: 'Farm Tools Ltd', item: 'NPK Fertilizer', quantity: 50, amount: 22000 },
            { date: '2024-01-13', supplier: 'Crop Care Inc', item: 'Garden Tools', quantity: 25, amount: 12000 },
            { date: '2024-01-12', supplier: 'Agri Solutions', item: 'Pesticides', quantity: 30, amount: 10000 },
            { date: '2024-01-11', supplier: 'Irrigation Pro', item: 'Irrigation Systems', quantity: 10, amount: 26000 },
          ]
        };

      case 'sales':
        return {
          title: 'Sales Report',
          mse: mse?.name || 'Unknown MSE',
          period: `${startDate} to ${endDate}`,
          summary: {
            totalSales: 38,
            totalAmount: 125000,
            averageSale: 3289,
            topCustomer: 'ABC Farm',
          },
          details: [
            { date: '2024-01-15', customer: 'ABC Farm', item: 'Organic Seeds', quantity: 80, amount: 25000 },
            { date: '2024-01-14', customer: 'XYZ Production', item: 'NPK Fertilizer', quantity: 40, amount: 30000 },
            { date: '2024-01-13', customer: 'DEF Trading', item: 'Garden Tools', quantity: 20, amount: 20000 },
            { date: '2024-01-12', customer: 'GHI Services', item: 'Pesticides', quantity: 25, amount: 15000 },
            { date: '2024-01-11', customer: 'JKL Farm', item: 'Irrigation Systems', quantity: 8, amount: 35000 },
          ]
        };

      default:
        return null;
    }
  };

  const handleGenerateReport = () => {
    if (!selectedMSE || !selectedReportType || !startDate || !endDate) {
      return;
    }

    const reportData = generateMockReportData(
      selectedReportType,
      selectedMSE,
      startDate,
      endDate
    );

    setCurrentReport(reportData);
    setOpenReportDialog(true);
  };

  const handleLockPeriod = () => {
    setIsPeriodLocked(!isPeriodLocked);
  };

  const handleDownloadReport = () => {
    // Implement download functionality
    console.log('Downloading report:', currentReport);
  };

  const renderReportTable = (reportData: any) => {
    if (!reportData) return null;

    const getTableHeaders = () => {
      switch (selectedReportType) {
        case 'income':
          return ['Date', 'Item', 'Sales', 'Purchases', 'Profit'];
        case 'stock':
          return ['Item', 'Purchased', 'Sold', 'Available', 'Status'];
        case 'purchases':
          return ['Date', 'Supplier', 'Item', 'Quantity', 'Amount'];
        case 'sales':
          return ['Date', 'Customer', 'Item', 'Quantity', 'Amount'];
        default:
          return [];
      }
    };

    const getTableRow = (item: any) => {
      switch (selectedReportType) {
        case 'income':
          return [
            item.date,
            item.item,
            `$${item.sales.toLocaleString()}`,
            `$${item.purchases.toLocaleString()}`,
            `$${item.profit.toLocaleString()}`,
          ];
        case 'stock':
          return [
            item.item,
            item.purchased,
            item.sold,
            item.available,
            <Chip
              label={item.status}
              size="small"
              className={
                item.status === 'In Stock'
                  ? 'bg-green-100 text-green-800'
                  : 'bg-yellow-100 text-yellow-800'
              }
            />,
          ];
        case 'purchases':
          return [
            item.date,
            item.supplier,
            item.item,
            item.quantity,
            `$${item.amount.toLocaleString()}`,
          ];
        case 'sales':
          return [
            item.date,
            item.customer,
            item.item,
            item.quantity,
            `$${item.amount.toLocaleString()}`,
          ];
        default:
          return [];
      }
    };

    return (
      <TableContainer component={Paper}>
        <Table>
          <TableHead>
            <TableRow className="bg-gray-50">
              {getTableHeaders().map((header) => (
                <TableCell key={header} className="font-semibold">
                  {header}
                </TableCell>
              ))}
            </TableRow>
          </TableHead>
          <TableBody>
            {reportData.details.map((item: any, index: number) => (
              <TableRow key={index} className="hover:bg-gray-50">
                {getTableRow(item).map((cell, cellIndex) => (
                  <TableCell key={cellIndex}>
                    {cell}
                  </TableCell>
                ))}
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>
    );
  };

  return (
    <Box className="space-y-6">
      {/* Header */}
      <Box className="flex justify-between items-center">
        <Typography variant="h4" className="font-bold text-gray-800">
          MSE Reports
        </Typography>
        <Box className="flex space-x-2">
          <Button
            variant="outlined"
            startIcon={<FilterList />}
            onClick={handleLockPeriod}
          >
            {isPeriodLocked ? 'Unlock Period' : 'Lock Period'}
          </Button>
          <Button
            variant="contained"
            startIcon={<Assessment />}
            className="bg-blue-600 hover:bg-blue-700"
          >
            Generate All Reports
          </Button>
        </Box>
      </Box>

      {/* Report Configuration */}
      <Paper className="p-6">
        <Typography variant="h6" className="font-semibold mb-4">
          Report Configuration
        </Typography>
        
        <Grid container spacing={3}>
          <Grid item xs={12} md={3}>
            <FormControl fullWidth>
              <InputLabel>Select MSE</InputLabel>
              <Select
                value={selectedMSE}
                onChange={(e: any) => setSelectedMSE(e.target.value)}
                label="Select MSE"
              >
                {mseList.map((mse) => (
                  <MenuItem key={mse.id} value={mse.id}>
                    {mse.name} ({mse.code})
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
          </Grid>

          <Grid item xs={12} md={3}>
            <DatePicker
              label="Start Date"
              value={startDate}
              onChange={setStartDate}
              disabled={isPeriodLocked}
              slotProps={{
                textField: {
                  fullWidth: true,
                  size: 'small',
                },
              }}
            />
          </Grid>

          <Grid item xs={12} md={3}>
            <DatePicker
              label="End Date"
              value={endDate}
              onChange={setEndDate}
              disabled={isPeriodLocked}
              slotProps={{
                textField: {
                  fullWidth: true,
                  size: 'small',
                },
              }}
            />
          </Grid>

          <Grid item xs={12} md={3}>
            <FormControl fullWidth>
              <InputLabel>Report Type</InputLabel>
              <Select
                value={selectedReportType}
                onChange={(e: any) => setSelectedReportType(e.target.value)}
                label="Report Type"
              >
                {reportTypes.map((type) => (
                  <MenuItem key={type.id} value={type.id}>
                    {type.title}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
          </Grid>
        </Grid>

        <Box className="flex justify-end mt-4">
          <Button
            variant="contained"
            onClick={handleGenerateReport}
            disabled={!selectedMSE || !selectedReportType || !startDate || !endDate}
            className="bg-blue-600 hover:bg-blue-700"
          >
            Generate Report
          </Button>
        </Box>
      </Paper>

      {/* Report Types Overview */}
      <Grid container spacing={3}>
        {reportTypes.map((reportType) => (
          <Grid item xs={12} sm={6} md={3} key={reportType.id}>
            <Card 
              className="h-full cursor-pointer hover:shadow-lg transition-shadow"
              onClick={() => setSelectedReportType(reportType.id)}
            >
              <CardContent>
                <Box className="flex items-center justify-between mb-3">
                  <Box className="p-2 bg-gray-100 rounded-lg">
                    {reportType.icon}
                  </Box>
                  <Chip
                    label={selectedReportType === reportType.id ? 'Selected' : 'Click to select'}
                    size="small"
                    className={
                      selectedReportType === reportType.id
                        ? 'bg-blue-100 text-blue-800'
                        : 'bg-gray-100 text-gray-600'
                    }
                  />
                </Box>
                <Typography variant="h6" className="font-semibold mb-2">
                  {reportType.title}
                </Typography>
                <Typography variant="body2" color="textSecondary">
                  {reportType.description}
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>

      {/* Period Lock Notice */}
      {isPeriodLocked && (
        <Alert severity="info" icon={<Lock />}>
          Report periods are locked to monthly intervals for all MSEs. This ensures consistent reporting across the system.
        </Alert>
      )}

      {/* Report Dialog */}
      <Dialog
        open={openReportDialog}
        onClose={() => setOpenReportDialog(false)}
        maxWidth="lg"
        fullWidth
      >
        <DialogTitle>
          <Box className="flex justify-between items-center">
            <Typography variant="h6">
              {currentReport?.title} - {currentReport?.mse}
            </Typography>
            <Box className="flex space-x-2">
              <Button
                variant="outlined"
                startIcon={<Download />}
                onClick={handleDownloadReport}
              >
                Download
              </Button>
              <Button
                variant="outlined"
                onClick={() => setOpenReportDialog(false)}
              >
                Close
              </Button>
            </Box>
          </Box>
        </DialogTitle>
        <DialogContent>
          {currentReport && (
            <Box className="space-y-4">
              {/* Report Summary */}
              <Paper className="p-4 bg-gray-50">
                <Typography variant="h6" className="font-semibold mb-3">
                  Report Summary
                </Typography>
                <Grid container spacing={2}>
                  {Object.entries(currentReport.summary).map(([key, value]) => (
                    <Grid item xs={6} md={3} key={key}>
                      <Box className="text-center">
                        <Typography variant="body2" color="textSecondary">
                          {key.replace(/([A-Z])/g, ' $1').replace(/^./, str => str.toUpperCase())}
                        </Typography>
                        <Typography variant="h6" className="font-semibold">
                          {(() => {
                            if (typeof value === 'number' && (key.includes('Amount') || key.includes('Profit') || key.includes('Sales') || key.includes('Purchases'))) {
                              return `$${value.toLocaleString()}`;
                            }
                            return String(value);
                          })()}
                        </Typography>
                      </Box>
                    </Grid>
                  ))}
                </Grid>
              </Paper>

              {/* Report Details */}
              <Typography variant="h6" className="font-semibold">
                Detailed Report
              </Typography>
              {renderReportTable(currentReport)}
            </Box>
          )}
        </DialogContent>
      </Dialog>
    </Box>
  );
};

export default Reports; 
