import React, { useState, useEffect } from 'react';
import {
  Box,
  Paper,
  Typography,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Button,
  Chip,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Alert,
  IconButton,
  Tooltip,
  Card,
  CardContent,
  Grid,
} from '@mui/material';
import {
  CheckCircle,
  Cancel,
  Visibility,
  Phone,
  Email,
  Business,
  Person,
  Schedule,
} from '@mui/icons-material';

const PendingRegistrations: React.FC = () => {
  const [pendingUsers, setPendingUsers] = useState<any[]>([]);
  const [selectedUser, setSelectedUser] = useState<any>(null);
  const [viewDialogOpen, setViewDialogOpen] = useState<boolean>(false);
  const [approveDialogOpen, setApproveDialogOpen] = useState<boolean>(false);
  const [rejectDialogOpen, setRejectDialogOpen] = useState<boolean>(false);
  const [otpCode, setOtpCode] = useState<string>('');
  const [loading, setLoading] = useState<boolean>(false);
  const [message, setMessage] = useState<{ type: string; text: string }>({ type: '', text: '' });

  // Mock data - replace with actual API call
  useEffect(() => {
    const mockPendingUsers = [
      {
        id: 1,
        firstName: 'John',
        lastName: 'Doe',
        email: 'john.doe@example.com',
        phone: '+1234567890',
        company: 'Tech Solutions Inc.',
        mseType: 'Input MSE',
        registrationDate: '2024-01-15T10:30:00Z',
        status: 'pending',
      },
      {
        id: 2,
        firstName: 'Jane',
        lastName: 'Smith',
        email: 'jane.smith@example.com',
        phone: '+1234567891',
        company: 'Digital Innovations Ltd.',
        mseType: 'Production MSE',
        registrationDate: '2024-01-14T15:45:00Z',
        status: 'pending',
      },
      {
        id: 3,
        firstName: 'Mike',
        lastName: 'Johnson',
        email: 'mike.johnson@example.com',
        phone: '+1234567892',
        company: 'Global Enterprises',
        mseType: 'Output MSE',
        registrationDate: '2024-01-13T09:20:00Z',
        status: 'pending',
      },
    ];
    setPendingUsers(mockPendingUsers);
  }, []);

  const handleViewUser = (user: any) => {
    setSelectedUser(user);
    setViewDialogOpen(true);
  };

  const handleApproveUser = (user: any) => {
    setSelectedUser(user);
    setApproveDialogOpen(true);
  };

  const handleRejectUser = (user: any) => {
    setSelectedUser(user);
    setRejectDialogOpen(true);
  };

  const handleApprove = async () => {
    if (!otpCode.trim()) {
      setMessage({ type: 'error', text: 'Please enter the OTP code' });
      return;
    }

    setLoading(true);
    try {
      // Simulate API call to approve user and send OTP
      await new Promise(resolve => setTimeout(resolve, 2000));
      
      // Update the user status in the list
      setPendingUsers(prev => 
        prev.map(user => 
          user.id === selectedUser.id 
            ? { ...user, status: 'approved' }
            : user
        )
      );

      setMessage({ type: 'success', text: 'User approved successfully! OTP has been sent to their phone number.' });
      setApproveDialogOpen(false);
      setOtpCode('');
      setSelectedUser(null);
    } catch (error) {
      setMessage({ type: 'error', text: 'Failed to approve user. Please try again.' });
    } finally {
      setLoading(false);
    }
  };

  const handleReject = async () => {
    setLoading(true);
    try {
      // Simulate API call to reject user
      await new Promise(resolve => setTimeout(resolve, 1000));
      
      // Remove user from pending list
      setPendingUsers(prev => prev.filter(user => user.id !== selectedUser.id));
      
      setMessage({ type: 'success', text: 'User registration rejected successfully.' });
      setRejectDialogOpen(false);
      setSelectedUser(null);
    } catch (error) {
      setMessage({ type: 'error', text: 'Failed to reject user. Please try again.' });
    } finally {
      setLoading(false);
    }
  };

  const formatDate = (dateString: string) => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  };

  return (
    <Box className="space-y-6">
      {/* Header */}
      <Box className="flex justify-between items-center">
        <Typography variant="h4" className="font-bold text-gray-800">
          Pending Registrations
        </Typography>
        <Chip 
          label={`${pendingUsers.length} Pending`} 
          color="warning" 
          icon={<Schedule />}
        />
      </Box>

      {/* Statistics Cards */}
      <Grid container spacing={3}>
        <Grid item xs={12} sm={6} md={3}>
          <Card className="h-full hover:shadow-lg transition-shadow">
            <CardContent>
              <Box className="flex items-center justify-between">
                <Box>
                  <Typography color="textSecondary" gutterBottom>
                    Total Pending
                  </Typography>
                  <Typography variant="h4" className="font-bold text-orange-600">
                    {pendingUsers.length}
                  </Typography>
                </Box>
                <Box className="p-2 bg-orange-100 rounded-lg">
                  <Schedule className="text-orange-600" />
                </Box>
              </Box>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Card className="h-full hover:shadow-lg transition-shadow">
            <CardContent>
              <Box className="flex items-center justify-between">
                <Box>
                  <Typography color="textSecondary" gutterBottom>
                    Approved Today
                  </Typography>
                  <Typography variant="h4" className="font-bold text-green-600">
                    5
                  </Typography>
                </Box>
                <Box className="p-2 bg-green-100 rounded-lg">
                  <CheckCircle className="text-green-600" />
                </Box>
              </Box>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Card className="h-full hover:shadow-lg transition-shadow">
            <CardContent>
              <Box className="flex items-center justify-between">
                <Box>
                  <Typography color="textSecondary" gutterBottom>
                    Rejected Today
                  </Typography>
                  <Typography variant="h4" className="font-bold text-red-600">
                    2
                  </Typography>
                </Box>
                <Box className="p-2 bg-red-100 rounded-lg">
                  <Cancel className="text-red-600" />
                </Box>
              </Box>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Card className="h-full hover:shadow-lg transition-shadow">
            <CardContent>
              <Box className="flex items-center justify-between">
                <Box>
                  <Typography color="textSecondary" gutterBottom>
                    Avg. Response Time
                  </Typography>
                  <Typography variant="h4" className="font-bold text-blue-600">
                    2.5h
                  </Typography>
                </Box>
                <Box className="p-2 bg-blue-100 rounded-lg">
                  <Schedule className="text-blue-600" />
                </Box>
              </Box>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Message Alert */}
      {message.text && (
        <Alert 
          severity={message.type as any} 
          onClose={() => setMessage({ type: '', text: '' })}
          className="mb-4"
        >
          {message.text}
        </Alert>
      )}

      {/* Pending Users Table */}
      <Paper className="overflow-hidden">
        <TableContainer>
          <Table>
            <TableHead>
              <TableRow className="bg-gray-50">
                <TableCell className="font-semibold">User</TableCell>
                <TableCell className="font-semibold">Contact</TableCell>
                <TableCell className="font-semibold">Company</TableCell>
                <TableCell className="font-semibold">MSE Type</TableCell>
                <TableCell className="font-semibold">Registration Date</TableCell>
                <TableCell className="font-semibold">Status</TableCell>
                <TableCell className="font-semibold">Actions</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {pendingUsers.map((user) => (
                <TableRow key={user.id} className="hover:bg-gray-50">
                  <TableCell>
                    <Box className="flex items-center space-x-2">
                      <Person className="text-gray-400" />
                      <Box>
                        <Typography variant="body2" className="font-medium">
                          {user.firstName} {user.lastName}
                        </Typography>
                        <Typography variant="caption" color="textSecondary">
                          ID: {user.id}
                        </Typography>
                      </Box>
                    </Box>
                  </TableCell>
                  <TableCell>
                    <Box className="space-y-1">
                      <Box className="flex items-center space-x-1">
                        <Email className="text-gray-400 text-sm" />
                        <Typography variant="body2">{user.email}</Typography>
                      </Box>
                      <Box className="flex items-center space-x-1">
                        <Phone className="text-gray-400 text-sm" />
                        <Typography variant="body2">{user.phone}</Typography>
                      </Box>
                    </Box>
                  </TableCell>
                  <TableCell>
                    <Box className="flex items-center space-x-1">
                      <Business className="text-gray-400" />
                      <Typography variant="body2">{user.company}</Typography>
                    </Box>
                  </TableCell>
                  <TableCell>
                    <Chip 
                      label={user.mseType} 
                      size="small"
                      className={
                        user.mseType === 'Input MSE' ? 'bg-blue-100 text-blue-800' :
                        user.mseType === 'Production MSE' ? 'bg-green-100 text-green-800' :
                        'bg-orange-100 text-orange-800'
                      }
                    />
                  </TableCell>
                  <TableCell>
                    <Typography variant="body2">
                      {formatDate(user.registrationDate)}
                    </Typography>
                  </TableCell>
                  <TableCell>
                    <Chip 
                      label="Pending" 
                      color="warning" 
                      size="small"
                    />
                  </TableCell>
                  <TableCell>
                    <Box className="flex space-x-1">
                      <Tooltip title="View Details">
                        <IconButton 
                          size="small" 
                          onClick={() => handleViewUser(user)}
                          className="text-blue-600"
                        >
                          <Visibility />
                        </IconButton>
                      </Tooltip>
                      <Tooltip title="Approve">
                        <IconButton 
                          size="small" 
                          onClick={() => handleApproveUser(user)}
                          className="text-green-600"
                        >
                          <CheckCircle />
                        </IconButton>
                      </Tooltip>
                      <Tooltip title="Reject">
                        <IconButton 
                          size="small" 
                          onClick={() => handleRejectUser(user)}
                          className="text-red-600"
                        >
                          <Cancel />
                        </IconButton>
                      </Tooltip>
                    </Box>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      </Paper>

      {/* View User Dialog */}
      <Dialog 
        open={viewDialogOpen} 
        onClose={() => setViewDialogOpen(false)}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>User Registration Details</DialogTitle>
        <DialogContent>
          {selectedUser && (
            <Box className="space-y-4 mt-2">
              <Grid container spacing={2}>
                <Grid item xs={6}>
                  <Typography variant="subtitle2" color="textSecondary">First Name</Typography>
                  <Typography variant="body1">{selectedUser.firstName}</Typography>
                </Grid>
                <Grid item xs={6}>
                  <Typography variant="subtitle2" color="textSecondary">Last Name</Typography>
                  <Typography variant="body1">{selectedUser.lastName}</Typography>
                </Grid>
              </Grid>
              <Box>
                <Typography variant="subtitle2" color="textSecondary">Email</Typography>
                <Typography variant="body1">{selectedUser.email}</Typography>
              </Box>
              <Box>
                <Typography variant="subtitle2" color="textSecondary">Phone</Typography>
                <Typography variant="body1">{selectedUser.phone}</Typography>
              </Box>
              <Box>
                <Typography variant="subtitle2" color="textSecondary">Company</Typography>
                <Typography variant="body1">{selectedUser.company}</Typography>
              </Box>
              <Box>
                <Typography variant="subtitle2" color="textSecondary">MSE Type</Typography>
                <Typography variant="body1">{selectedUser.mseType}</Typography>
              </Box>
              <Box>
                <Typography variant="subtitle2" color="textSecondary">Registration Date</Typography>
                <Typography variant="body1">{formatDate(selectedUser.registrationDate)}</Typography>
              </Box>
            </Box>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setViewDialogOpen(false)}>Close</Button>
        </DialogActions>
      </Dialog>

      {/* Approve User Dialog */}
      <Dialog 
        open={approveDialogOpen} 
        onClose={() => setApproveDialogOpen(false)}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>Approve User Registration</DialogTitle>
        <DialogContent>
          {selectedUser && (
            <Box className="space-y-4 mt-2">
              <Alert severity="info">
                Approving this user will send an OTP to their phone number ({selectedUser.phone}) 
                for account activation.
              </Alert>
              <Box>
                <Typography variant="subtitle2" color="textSecondary" gutterBottom>
                  User: {selectedUser.firstName} {selectedUser.lastName}
                </Typography>
                <Typography variant="subtitle2" color="textSecondary" gutterBottom>
                  Company: {selectedUser.company}
                </Typography>
              </Box>
              <TextField
                fullWidth
                label="OTP Code (for verification)"
                value={otpCode}
                onChange={(e) => setOtpCode(e.target.value)}
                placeholder="Enter OTP code"
                helperText="This OTP will be sent to the user's phone number"
              />
            </Box>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setApproveDialogOpen(false)}>Cancel</Button>
          <Button 
            onClick={handleApprove} 
            variant="contained" 
            color="success"
            disabled={loading}
          >
            {loading ? 'Approving...' : 'Approve & Send OTP'}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Reject User Dialog */}
      <Dialog 
        open={rejectDialogOpen} 
        onClose={() => setRejectDialogOpen(false)}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>Reject User Registration</DialogTitle>
        <DialogContent>
          {selectedUser && (
            <Box className="space-y-4 mt-2">
              <Alert severity="warning">
                Are you sure you want to reject this user registration? 
                This action cannot be undone.
              </Alert>
              <Box>
                <Typography variant="subtitle2" color="textSecondary" gutterBottom>
                  User: {selectedUser.firstName} {selectedUser.lastName}
                </Typography>
                <Typography variant="subtitle2" color="textSecondary" gutterBottom>
                  Email: {selectedUser.email}
                </Typography>
                <Typography variant="subtitle2" color="textSecondary" gutterBottom>
                  Company: {selectedUser.company}
                </Typography>
              </Box>
            </Box>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setRejectDialogOpen(false)}>Cancel</Button>
          <Button 
            onClick={handleReject} 
            variant="contained" 
            color="error"
            disabled={loading}
          >
            {loading ? 'Rejecting...' : 'Reject Registration'}
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default PendingRegistrations; 
