import React, { useState } from 'react';
import {
  Box,
  Typography,
  Paper,
  TextField,
  Button,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Alert,
  Grid,
  Divider,
  CircularProgress,
} from '@mui/material';
import {
  Person,
  Phone,
  Email,
  LocationOn,
  Work,
  Save,
} from '@mui/icons-material';
import { useAuth } from '../../context/AuthContext';
import { api } from '../../config/api';

const RegisterStaff: React.FC = () => {
  const { user: currentUser } = useAuth();
  const [formData, setFormData] = useState<{
    firstName: string;
    lastName: string;
    email: string;
    phone: string;
    department: string;
    position: string;
    role: string;
    startDate: string;
    salary: string;
    address: string;
    password: string;
    confirmPassword: string;
  }>({
    firstName: '',
    lastName: '',
    email: '',
    phone: '',
    department: '',
    position: '',
    role: '',
    startDate: '',
    salary: '',
    address: '',
    password: '',
    confirmPassword: '',
  });
  const [success, setSuccess] = useState<string>('');
  const [error, setError] = useState<string>('');
  const [loading, setLoading] = useState<boolean>(false);

  const departments = [
    'Administration',
    'Finance',
    'Operations',
    'Sales',
    'Marketing',
    'IT',
    'Human Resources',
  ];

  const positions = [
    'Manager',
    'Supervisor',
    'Coordinator',
    'Specialist',
    'Assistant',
    'Analyst',
  ];

  // Only show Admin role if current user is Admin
  const roles = currentUser?.role === 'Admin' 
    ? ['Admin', 'Input MSE', 'Production MSE', 'Output MSE']
    : ['Input MSE', 'Production MSE', 'Output MSE'];

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement> | any) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value,
    });
  };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    // Validation
    if (!formData.firstName || !formData.lastName || !formData.email || !formData.password) {
      setError('Please fill in all required fields');
      return;
    }

    if (formData.password !== formData.confirmPassword) {
      setError('Passwords do not match');
      return;
    }

    if (formData.password.length < 6) {
      setError('Password must be at least 6 characters long');
      return;
    }

    // Check if non-admin is trying to create admin
    if (formData.role === 'Admin' && currentUser?.role !== 'Admin') {
      setError('Only administrators can create admin accounts');
      return;
    }

    setLoading(true);

    try {
      // Prepare user data for API
      const userData = {
        first_name: formData.firstName,
        last_name: formData.lastName,
        email: formData.email,
        phone: formData.phone,
        password: formData.password,
        role: formData.role,
        department: formData.department,
        position: formData.position,
        address: formData.address,
        start_date: formData.startDate,
        salary: formData.salary ? parseFloat(formData.salary) : null,
        // For MSE users, we'll need to handle MSE-specific fields
        ...(formData.role !== 'Admin' && {
          mse_type: formData.role,
          // Add MSE code if needed
        }),
      };

      const response = await api.users.create(userData);
      
      if (response.success) {
        setSuccess(`Staff member registered successfully! ${formData.role === 'Admin' ? 'Admin account created.' : 'User will receive login credentials.'}`);
        setFormData({
          firstName: '',
          lastName: '',
          email: '',
          phone: '',
          department: '',
          position: '',
          role: '',
          startDate: '',
          salary: '',
          address: '',
          password: '',
          confirmPassword: '',
        });
      } else {
        setError(response.message || 'Failed to register staff member');
      }
    } catch (err: any) {
      console.error('Registration error:', err);
      setError(err.message || 'Failed to register staff member. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Box className="space-y-6">
      <Box className="flex justify-between items-center">
        <Typography variant="h5" className="font-semibold text-gray-800">
          Register New Staff Member
        </Typography>
        <Button
          variant="contained"
          startIcon={<Person />}
          className="bg-blue-600 hover:bg-blue-700"
        >
          View All Staff
        </Button>
      </Box>

      {/* Admin Creation Notice */}
      {currentUser?.role === 'Admin' && (
        <Alert severity="info" className="mb-4">
          <Typography variant="body2">
            <strong>Admin Privilege:</strong> You can create admin accounts for other administrators. 
            Only existing admins can create new admin users to maintain system security.
          </Typography>
        </Alert>
      )}

      {error && <Alert severity="error">{error}</Alert>}
      {success && <Alert severity="success">{success}</Alert>}

      <Paper className="p-6">
        <form onSubmit={handleSubmit}>
          <Grid container spacing={3}>
            {/* Personal Information */}
            <Grid item xs={12}>
              <Box className="flex items-center space-x-2 mb-4">
                <Person className="text-blue-600" />
                <Typography variant="h6" className="font-semibold">
                  Personal Information
                </Typography>
              </Box>
            </Grid>

            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="First Name"
                name="firstName"
                value={formData.firstName}
                onChange={handleChange}
                required
                InputProps={{
                  startAdornment: <Person className="text-gray-400 mr-2" />,
                }}
              />
            </Grid>

            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="Last Name"
                name="lastName"
                value={formData.lastName}
                onChange={handleChange}
                required
                InputProps={{
                  startAdornment: <Person className="text-gray-400 mr-2" />,
                }}
              />
            </Grid>

            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="Email Address"
                name="email"
                type="email"
                value={formData.email}
                onChange={handleChange}
                required
                InputProps={{
                  startAdornment: <Email className="text-gray-400 mr-2" />,
                }}
              />
            </Grid>

            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="Phone Number"
                name="phone"
                value={formData.phone}
                onChange={handleChange}
                InputProps={{
                  startAdornment: <Phone className="text-gray-400 mr-2" />,
                }}
              />
            </Grid>

            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Address"
                name="address"
                value={formData.address}
                onChange={handleChange}
                multiline
                rows={2}
                InputProps={{
                  startAdornment: <LocationOn className="text-gray-400 mr-2" />,
                }}
              />
            </Grid>

            <Grid item xs={12}>
              <Divider className="my-4" />
            </Grid>

            {/* Employment Information */}
            <Grid item xs={12}>
              <Box className="flex items-center space-x-2 mb-4">
                <Work className="text-green-600" />
                <Typography variant="h6" className="font-semibold">
                  Employment Information
                </Typography>
              </Box>
            </Grid>

            <Grid item xs={12} md={6}>
              <FormControl fullWidth>
                <InputLabel>Department</InputLabel>
                <Select
                  name="department"
                  value={formData.department}
                  onChange={handleChange}
                  label="Department"
                >
                  {departments.map((dept) => (
                    <MenuItem key={dept} value={dept}>
                      {dept}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>

            <Grid item xs={12} md={6}>
              <FormControl fullWidth>
                <InputLabel>Position</InputLabel>
                <Select
                  name="position"
                  value={formData.position}
                  onChange={handleChange}
                  label="Position"
                >
                  {positions.map((pos) => (
                    <MenuItem key={pos} value={pos}>
                      {pos}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>

            <Grid item xs={12} md={6}>
              <FormControl fullWidth>
                <InputLabel>Role</InputLabel>
                <Select
                  name="role"
                  value={formData.role}
                  onChange={handleChange}
                  label="Role"
                >
                  {roles.map((role) => (
                    <MenuItem key={role} value={role}>
                      {role}
                    </MenuItem>
                  ))}
                </Select>
                {currentUser?.role === 'Admin' && (
                  <Typography variant="caption" color="textSecondary" className="mt-1">
                    Only admins can create admin accounts
                  </Typography>
                )}
              </FormControl>
            </Grid>

            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="Start Date"
                name="startDate"
                type="date"
                value={formData.startDate}
                onChange={handleChange}
                InputLabelProps={{
                  shrink: true,
                }}
              />
            </Grid>

            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="Salary"
                name="salary"
                type="number"
                value={formData.salary}
                onChange={handleChange}
                placeholder="e.g., 50000"
                InputProps={{
                  startAdornment: '$',
                }}
              />
            </Grid>

            <Grid item xs={12}>
              <Divider className="my-4" />
            </Grid>

            {/* Account Information */}
            <Grid item xs={12}>
              <Box className="flex items-center space-x-2 mb-4">
                <Person className="text-purple-600" />
                <Typography variant="h6" className="font-semibold">
                  Account Information
                </Typography>
              </Box>
            </Grid>

            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="Password"
                name="password"
                type="password"
                value={formData.password}
                onChange={handleChange}
                required
                helperText="Minimum 6 characters"
              />
            </Grid>

            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="Confirm Password"
                name="confirmPassword"
                type="password"
                value={formData.confirmPassword}
                onChange={handleChange}
                required
              />
            </Grid>

            <Grid item xs={12}>
              <Box className="flex justify-end space-x-2 pt-4">
                <Button
                  variant="outlined"
                  onClick={() => {
                    setFormData({
                      firstName: '',
                      lastName: '',
                      email: '',
                      phone: '',
                      department: '',
                      position: '',
                      role: '',
                      startDate: '',
                      salary: '',
                      address: '',
                      password: '',
                      confirmPassword: '',
                    });
                  }}
                  disabled={loading}
                >
                  Clear Form
                </Button>
                <Button
                  type="submit"
                  variant="contained"
                  startIcon={loading ? <CircularProgress size={20} /> : <Save />}
                  className="bg-blue-600 hover:bg-blue-700"
                  disabled={loading}
                >
                  {loading ? 'Creating Account...' : 'Register Staff'}
                </Button>
              </Box>
            </Grid>
          </Grid>
        </form>
      </Paper>
    </Box>
  );
};

export default RegisterStaff; 
