import React, { useState } from 'react';
import { Outlet, useLocation, Link } from 'react-router-dom';
import {
  AppBar,
  Toolbar,
  Typography,
  Button,
  IconButton,
  Avatar,
  Menu,
  MenuItem,
  Box,
  Badge,
  Chip,
  Popper,
  Grow,
  Paper,
  ClickAwayListener,
  ListItemIcon,
  Divider,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  Grid,
  Card,
  CardContent,
  List,
  ListItem,
  ListItemText,
  ListItemAvatar,
} from '@mui/material';
import {
  Dashboard,
  People,
  Business,
  Store,
  Assessment,
  Analytics as AnalyticsIcon,
  Notifications,
  AccountCircle,
  Logout,
  ExpandMore,
  TrendingUp,
  Inventory,
  ShoppingCart,
  AttachMoney,
  Email,
  Phone,
  LocationOn,
  Edit,
} from '@mui/icons-material';
import { useAuth } from '../../context/AuthContext';

interface MenuItemType {
  text: string;
  icon: React.ReactNode;
  path: string;
}

interface ReportMenuItem {
  text: string;
  icon: React.ReactNode;
  path: string;
}

// Admin menu items - full access
const adminMenuItems: MenuItemType[] = [
  { text: 'Dashboard', icon: <Dashboard />, path: '/dashboard' },
  { text: 'Users', icon: <People />, path: '/users' },
  { text: 'MSEs', icon: <Business />, path: '/mses' },
  { text: 'Markets', icon: <Store />, path: '/markets' },
  { text: 'Analytics', icon: <AnalyticsIcon />, path: '/analytics' },
];

// MSE user menu items - limited access
const mseMenuItems: MenuItemType[] = [
  { text: 'Dashboard', icon: <Dashboard />, path: '/dashboard' },
  { text: 'Reports', icon: <Assessment />, path: '/reports' },
  { text: 'Analytics', icon: <AnalyticsIcon />, path: '/analytics' },
  { text: 'Wallet', icon: <AttachMoney />, path: '/mses/wallet' },
];

// Get menu items based on user role
const getMenuItems = (userRole?: string): MenuItemType[] => {
  if (userRole === 'Admin') {
    return adminMenuItems;
  }
  return mseMenuItems;
};

const reportMenuItems: ReportMenuItem[] = [
  { text: 'Income Report', icon: <TrendingUp />, path: '/reports/income' },
  { text: 'Stock Balance Report', icon: <Inventory />, path: '/reports/stock' },
  { text: 'Purchases Report', icon: <ShoppingCart />, path: '/reports/purchases' },
  { text: 'Sales Report', icon: <AttachMoney />, path: '/reports/sales' },
];

const Layout: React.FC = () => {
  const [anchorEl, setAnchorEl] = useState<null | HTMLElement>(null);
  const [reportsAnchorEl, setReportsAnchorEl] = useState<null | HTMLElement>(null);
  const [profileModalOpen, setProfileModalOpen] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const { user, logout } = useAuth();
  const location = useLocation();

  const handleProfileMenuOpen = (event: React.MouseEvent<HTMLElement>) => {
    setAnchorEl(event.currentTarget);
  };

  const handleProfileMenuClose = () => {
    setAnchorEl(null);
  };

  const handleReportsMenuOpen = (event: React.MouseEvent<HTMLElement>) => {
    setReportsAnchorEl(event.currentTarget);
  };

  const handleReportsMenuClose = () => {
    setReportsAnchorEl(null);
  };

  const handleLogout = () => {
    logout();
    handleProfileMenuClose();
  };

  const handleProfileClick = () => {
    setProfileModalOpen(true);
    handleProfileMenuClose();
  };

  const handleProfileModalClose = () => {
    setProfileModalOpen(false);
    setIsEditing(false);
  };

  const handleEditProfile = () => {
    setIsEditing(true);
  };

  const handleSaveProfile = () => {
    // TODO: Implement profile update logic
    setIsEditing(false);
  };

  const handleCancelEdit = () => {
    setIsEditing(false);
  };

  const isActive = (path: string): boolean => {
    return location.pathname.startsWith(path);
  };

  const isReportsActive = (): boolean => {
    return location.pathname.startsWith('/reports');
  };

  return (
    <Box className="flex flex-col h-screen bg-gray-50">
      {/* Top Navigation Bar */}
      <AppBar
        position="static"
        className="bg-white border-b border-gray-200 shadow-sm"
        elevation={0}
      >
        <Toolbar className="flex justify-between px-6">
          {/* Left side - Logo and Navigation */}
          <Box className="flex items-center space-x-8">
            {/* Logo */}
            <Typography variant="h6" className="font-bold text-blue-600">
              Finwise
            </Typography>

            {/* Navigation Items */}
            <Box className="flex items-center space-x-2">
              {getMenuItems(user?.role).map((item) => (
                <Button
                  key={item.text}
                  component={Link}
                  to={item.path}
                  startIcon={item.icon}
                  className={`px-4 py-2 rounded-lg transition-colors ${
                    isActive(item.path)
                      ? 'bg-blue-100 text-blue-700 hover:bg-blue-200'
                      : 'text-gray-600 hover:bg-gray-100'
                  }`}
                  variant={isActive(item.path) ? 'contained' : 'text'}
                  disableElevation
                >
                  {item.text}
                </Button>
              ))}

              {/* Reports Dropdown - Only for Admin */}
              {user?.role === 'Admin' && (
                <Button
                  startIcon={<Assessment />}
                  endIcon={<ExpandMore />}
                  onClick={handleReportsMenuOpen}
                  className={`px-4 py-2 rounded-lg transition-colors ${
                    isReportsActive()
                      ? 'bg-blue-100 text-blue-700 hover:bg-blue-200'
                      : 'text-gray-600 hover:bg-gray-100'
                  }`}
                  variant={isReportsActive() ? 'contained' : 'text'}
                  disableElevation
                >
                  Reports
                </Button>
              )}
            </Box>
          </Box>

          {/* Right side - User Profile and Notifications */}
          <Box className="flex items-center space-x-4">
            <IconButton className="text-gray-600 hover:bg-gray-100">
              <Badge badgeContent={3} color="error">
                <Notifications />
              </Badge>
            </IconButton>
            
            <Chip
              label={user?.role || 'User'}
              size="small"
              className="bg-blue-100 text-blue-800"
            />
            
            <IconButton
              onClick={handleProfileMenuOpen}
              className="text-gray-600 hover:bg-gray-100"
            >
              <Avatar className="w-8 h-8 bg-blue-500">
                {user?.name?.charAt(0) || 'U'}
              </Avatar>
            </IconButton>
          </Box>
        </Toolbar>
      </AppBar>

      {/* Reports Dropdown Menu */}
      <Popper
        open={Boolean(reportsAnchorEl)}
        anchorEl={reportsAnchorEl}
        placement="bottom-start"
        transition
        className="z-50"
      >
        {({ TransitionProps }) => (
          <Grow {...TransitionProps}>
            <Paper className="shadow-lg border border-gray-200 mt-1">
              <ClickAwayListener onClickAway={handleReportsMenuClose}>
                <Box className="py-2">
                  {reportMenuItems.map((item) => (
                    <MenuItem
                      key={item.text}
                      component={Link}
                      to={item.path}
                      onClick={handleReportsMenuClose}
                      className={`px-4 py-2 hover:bg-blue-50 ${
                        location.pathname === item.path ? 'bg-blue-100' : ''
                      }`}
                    >
                      <ListItemIcon className="text-gray-600">
                        {item.icon}
                      </ListItemIcon>
                      <Typography
                        className={
                          location.pathname === item.path
                            ? 'text-blue-700 font-medium'
                            : 'text-gray-700'
                        }
                      >
                        {item.text}
                      </Typography>
                    </MenuItem>
                  ))}
                </Box>
              </ClickAwayListener>
            </Paper>
          </Grow>
        )}
      </Popper>

      {/* Main Content Area */}
      <Box className="flex-1 overflow-auto">
        <Box className="p-6">
          <Outlet />
        </Box>
      </Box>

      {/* Profile Menu */}
      <Menu
        anchorEl={anchorEl}
        open={Boolean(anchorEl)}
        onClose={handleProfileMenuClose}
        className="mt-2"
        PaperProps={{
          className: 'shadow-lg border border-gray-200',
        }}
      >
        <MenuItem onClick={handleProfileClick}>
          <ListItemIcon>
            <AccountCircle fontSize="small" />
          </ListItemIcon>
          Profile
        </MenuItem>
        <Divider />
        <MenuItem onClick={handleLogout}>
          <ListItemIcon>
            <Logout fontSize="small" />
          </ListItemIcon>
          Logout
        </MenuItem>
      </Menu>

      {/* Profile Modal */}
      <Dialog
        open={profileModalOpen}
        onClose={handleProfileModalClose}
        maxWidth="md"
        fullWidth
        PaperProps={{
          className: 'rounded-lg',
        }}
      >
        <DialogTitle className="bg-blue-50 border-b border-blue-200">
          <Box className="flex items-center justify-between">
            <Typography variant="h6" className="font-semibold text-blue-800">
              User Profile
            </Typography>
            {!isEditing && (
              <IconButton
                onClick={handleEditProfile}
                className="text-blue-600 hover:bg-blue-100"
                size="small"
              >
                <Edit />
              </IconButton>
            )}
          </Box>
        </DialogTitle>

        <DialogContent className="p-6">
          {isEditing ? (
            // Edit Mode
            <Grid container spacing={3}>
              <Grid item xs={12} md={4}>
                <Box className="text-center">
                  <Avatar
                    className="w-24 h-24 mx-auto mb-4 bg-blue-500 text-2xl"
                  >
                    {user?.name?.charAt(0) || 'U'}
                  </Avatar>
                  <Button
                    variant="outlined"
                    size="small"
                    className="text-blue-600 border-blue-600"
                  >
                    Change Photo
                  </Button>
                </Box>
              </Grid>
              <Grid item xs={12} md={8}>
                <Grid container spacing={2}>
                  <Grid item xs={12} sm={6}>
                    <TextField
                      fullWidth
                      label="Full Name"
                      defaultValue={user?.name}
                      variant="outlined"
                      size="small"
                    />
                  </Grid>
                  <Grid item xs={12} sm={6}>
                    <TextField
                      fullWidth
                      label="Email"
                      defaultValue={user?.email}
                      variant="outlined"
                      size="small"
                      type="email"
                    />
                  </Grid>
                  <Grid item xs={12} sm={6}>
                    <TextField
                      fullWidth
                      label="Phone"
                      defaultValue={user?.phone || ''}
                      variant="outlined"
                      size="small"
                    />
                  </Grid>
                  <Grid item xs={12} sm={6}>
                    <TextField
                      fullWidth
                      label="Company"
                      defaultValue={user?.company || ''}
                      variant="outlined"
                      size="small"
                    />
                  </Grid>
                  <Grid item xs={12}>
                    <TextField
                      fullWidth
                      label="Location"
                      defaultValue={user?.location || ''}
                      variant="outlined"
                      size="small"
                    />
                  </Grid>
                  {user?.role !== 'Admin' && (
                    <>
                      <Grid item xs={12} sm={6}>
                        <TextField
                          fullWidth
                          label="MSE Type"
                          defaultValue={user?.mseType || ''}
                          variant="outlined"
                          size="small"
                          disabled
                        />
                      </Grid>
                      <Grid item xs={12} sm={6}>
                        <TextField
                          fullWidth
                          label="MSE Code"
                          defaultValue={user?.mseCode || ''}
                          variant="outlined"
                          size="small"
                          disabled
                        />
                      </Grid>
                    </>
                  )}
                </Grid>
              </Grid>
            </Grid>
          ) : (
            // View Mode
            <Grid container spacing={3}>
              <Grid item xs={12} md={4}>
                <Box className="text-center">
                  <Avatar
                    className="w-24 h-24 mx-auto mb-4 bg-blue-500 text-2xl"
                  >
                    {user?.name?.charAt(0) || 'U'}
                  </Avatar>
                  <Typography variant="h6" className="font-semibold mb-1">
                    {user?.name}
                  </Typography>
                  <Chip
                    label={user?.role}
                    size="small"
                    className="bg-blue-100 text-blue-800"
                  />
                </Box>
              </Grid>
              <Grid item xs={12} md={8}>
                <Card className="shadow-sm">
                  <CardContent>
                    <List>
                      <ListItem>
                        <ListItemAvatar>
                          <Avatar className="bg-blue-100 text-blue-600">
                            <Email />
                          </Avatar>
                        </ListItemAvatar>
                        <ListItemText
                          primary="Email"
                          secondary={user?.email}
                        />
                      </ListItem>
                      <ListItem>
                        <ListItemAvatar>
                          <Avatar className="bg-green-100 text-green-600">
                            <Phone />
                          </Avatar>
                        </ListItemAvatar>
                        <ListItemText
                          primary="Phone"
                          secondary={user?.phone || 'Not provided'}
                        />
                      </ListItem>
                      <ListItem>
                        <ListItemAvatar>
                          <Avatar className="bg-purple-100 text-purple-600">
                            <Business />
                          </Avatar>
                        </ListItemAvatar>
                        <ListItemText
                          primary="Company"
                          secondary={user?.company || 'Not provided'}
                        />
                      </ListItem>
                      <ListItem>
                        <ListItemAvatar>
                          <Avatar className="bg-orange-100 text-orange-600">
                            <LocationOn />
                          </Avatar>
                        </ListItemAvatar>
                        <ListItemText
                          primary="Location"
                          secondary={user?.location || 'Not provided'}
                        />
                      </ListItem>
                      {user?.role !== 'Admin' && (
                        <>
                          <ListItem>
                            <ListItemAvatar>
                              <Avatar className="bg-red-100 text-red-600">
                                <Business />
                              </Avatar>
                            </ListItemAvatar>
                            <ListItemText
                              primary="MSE Type"
                              secondary={user?.mseType || 'Not applicable'}
                            />
                          </ListItem>
                          <ListItem>
                            <ListItemAvatar>
                              <Avatar className="bg-indigo-100 text-indigo-600">
                                <AccountCircle />
                              </Avatar>
                            </ListItemAvatar>
                            <ListItemText
                              primary="MSE Code"
                              secondary={user?.mseCode || 'Not applicable'}
                            />
                          </ListItem>
                        </>
                      )}
                    </List>
                  </CardContent>
                </Card>
              </Grid>
            </Grid>
          )}
        </DialogContent>

        <DialogActions className="p-4 border-t border-gray-200">
          {isEditing ? (
            <>
              <Button
                onClick={handleCancelEdit}
                variant="outlined"
                className="text-gray-600 border-gray-300"
              >
                Cancel
              </Button>
              <Button
                onClick={handleSaveProfile}
                variant="contained"
                className="bg-blue-600 hover:bg-blue-700"
              >
                Save Changes
              </Button>
            </>
          ) : (
            <Button
              onClick={handleProfileModalClose}
              variant="contained"
              className="bg-blue-600 hover:bg-blue-700"
            >
              Close
            </Button>
          )}
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default Layout; 