import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { ThemeProvider, createTheme } from '@mui/material/styles';
import CssBaseline from '@mui/material/CssBaseline';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import { AdapterDateFns } from '@mui/x-date-pickers/AdapterDateFns';
import { Box, CircularProgress } from '@mui/material';

// Components
import Login from './components/auth/Login';
import Register from './components/auth/Register';
import OTPVerification from './components/auth/OTPVerification';
import Dashboard from './components/dashboard/Dashboard';
import Layout from './components/layout/Layout';
import Users from './components/users/Users';
import MSEs from './components/mses/MSEs';
import Markets from './components/markets/Markets';
import Reports from './components/reports/Reports';
import Analytics from './components/reports/Analytics';
import ProtectedRoute from './components/auth/ProtectedRoute';
import MSEWallet from './components/mses/MSEWallet';

// Individual Report Components
import IncomeReport from './components/reports/IncomeReport';
import StockReport from './components/reports/StockReport';
import PurchasesReport from './components/reports/PurchasesReport';
import SalesReport from './components/reports/SalesReport';

// Context
import { AuthProvider, useAuth } from './context/AuthContext';

const theme = createTheme({
  palette: {
    primary: {
      main: '#dc2626',
    },
    secondary: {
      main: '#1e3a8a',
    },
    background: {
        default: '#f8fafc',
    },
    text: {
        primary: '#334155',
    },
  },
  typography: {
    fontFamily: 'Roboto, sans-serif',
  },
});

const AppRoutes: React.FC = () => {
  const { isAuthenticated, loading } = useAuth();

  // Show loading spinner while checking authentication
  if (loading) {
    return (
      <Box className="flex justify-center items-center min-h-screen">
        <CircularProgress />
      </Box>
    );
  }

  if (!isAuthenticated) {
    return (
      <Routes>
        <Route path="/login" element={<Login />} />
        <Route path="/register" element={<Register />} />
        <Route path="/verify-otp" element={<OTPVerification />} />
        <Route path="*" element={<Navigate to="/login" />} />
      </Routes>
    );
  }

  return (
    <Routes>
      <Route path="/" element={<Layout />}>
        <Route index element={<Navigate to="/dashboard" />} />
        <Route path="dashboard" element={<Dashboard />} />
        
        {/* Admin-only routes */}
        <Route path="users/*" element={
          <ProtectedRoute allowedRoles={['Admin']}>
            <Users />
          </ProtectedRoute>
        } />
        <Route path="mses/*" element={
          <ProtectedRoute allowedRoles={['Admin']}>
            <MSEs />
          </ProtectedRoute>
        } />
        <Route path="markets/*" element={
          <ProtectedRoute allowedRoles={['Admin']}>
            <Markets />
          </ProtectedRoute>
        } />
        
        {/* Reports - Admin has access to all, MSE users have access to their reports */}
        <Route path="reports" element={<Reports />} />
        <Route path="reports/income" element={<IncomeReport />} />
        <Route path="reports/stock" element={<StockReport />} />
        <Route path="reports/purchases" element={<PurchasesReport />} />
        <Route path="reports/sales" element={<SalesReport />} />
        
        {/* Analytics - Available to all authenticated users */}
        <Route path="analytics" element={<Analytics />} />
        
        {/* MSE Wallet - Only for MSE users */}
        <Route path="mses/wallet" element={
          <ProtectedRoute allowedRoles={['Input MSE', 'Production MSE', 'Output MSE']}>
            <MSEWallet />
          </ProtectedRoute>
        } />
        
        <Route path="*" element={<Navigate to="/dashboard" />} />
      </Route>
    </Routes>
  );
};

const App: React.FC = () => {
  return (
    <ThemeProvider theme={theme}>
      <CssBaseline />
      <LocalizationProvider dateAdapter={AdapterDateFns}>
        <AuthProvider>
          <Router>
            <AppRoutes />
          </Router>
        </AuthProvider>
      </LocalizationProvider>
    </ThemeProvider>
  );
};

export default App; 