import React, { useState, useEffect } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import {
  Box,
  Paper,
  TextField,
  Button,
  Typography,
  Alert,
  InputAdornment,
  IconButton,
  CircularProgress,
  Grid,
} from '@mui/material';
import {
  Visibility,
  VisibilityOff,
  Lock,
  Phone,
  Email,
  Person,
  Business,
  Store,
  Timer,
} from '@mui/icons-material';

interface OTPFormData {
  otp: string;
  password: string;
  confirmPassword: string;
}

const OTPVerification: React.FC = () => {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  
  const [formData, setFormData] = useState<OTPFormData>({
    otp: '',
    password: '',
    confirmPassword: '',
  });
  const [showPassword, setShowPassword] = useState<boolean>(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState<boolean>(false);
  const [error, setError] = useState<string>('');
  const [success, setSuccess] = useState<string>('');
  const [loading, setLoading] = useState<boolean>(false);
  const [resendLoading, setResendLoading] = useState<boolean>(false);
  const [timeLeft, setTimeLeft] = useState<number>(300); // 5 minutes
  const [canResend, setCanResend] = useState<boolean>(false);
  
  // Get user data from URL params (in real app, this would come from the backend)
  const userEmail = searchParams.get('email') || 'user@example.com';
  const userPhone = searchParams.get('phone') || '+1234567890';
  const userName = searchParams.get('name') || 'John Doe';
  const userCompany = searchParams.get('company') || 'Example Company';
  const userMseType = searchParams.get('mseType') || 'Input MSE';

  useEffect(() => {
    const timer = setInterval(() => {
      setTimeLeft((prev) => {
        if (prev <= 1) {
          setCanResend(true);
          return 0;
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(timer);
  }, []);

  const formatTime = (seconds: number): string => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    });
  };

  const handleResendOTP = async (): Promise<void> => {
    setResendLoading(true);
    setError('');
    
    try {
      // Simulate API call to resend OTP
      await new Promise(resolve => setTimeout(resolve, 2000));
      
      setTimeLeft(300); // Reset timer to 5 minutes
      setCanResend(false);
      setSuccess('OTP has been resent to your phone number.');
    } catch (err) {
      setError('Failed to resend OTP. Please try again.');
    } finally {
      setResendLoading(false);
    }
  };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    if (formData.password !== formData.confirmPassword) {
      setError('Passwords do not match');
      return;
    }

    if (formData.password.length < 6) {
      setError('Password must be at least 6 characters long');
      return;
    }

    if (!formData.otp || formData.otp.length !== 6) {
      setError('Please enter a valid 6-digit OTP');
      return;
    }

    setLoading(true);

    try {
      // Simulate API call to verify OTP and set password
      await new Promise(resolve => setTimeout(resolve, 2000));
      
      setSuccess('Account activated successfully! You can now sign in.');
      setTimeout(() => {
        navigate('/login');
      }, 2000);
    } catch (err) {
      setError('Invalid OTP or an error occurred. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 flex items-center justify-center p-4">
      <Box className="w-full max-w-2xl">
        <Paper elevation={8} className="p-8 rounded-2xl">
          <div className="text-center mb-8">
            <Typography variant="h4" component="h1" className="font-bold text-gray-800 mb-2">
              FInwise
            </Typography>
            <Typography variant="body2" color="textSecondary">
              Complete Your Registration
            </Typography>
          </div>

          {error && (
            <Alert severity="error" className="mb-4">
              {error}
            </Alert>
          )}

          {success && (
            <Alert severity="success" className="mb-4">
              {success}
            </Alert>
          )}

          {/* User Information Display */}
          <Paper variant="outlined" className="p-4 mb-6 bg-blue-50">
            <Typography variant="h6" className="font-semibold mb-3 text-blue-800">
              Registration Details
            </Typography>
            <Grid container spacing={2}>
              <Grid item xs={12} sm={6}>
                <Box className="flex items-center space-x-2">
                  <Person className="text-blue-600" />
                  <Box>
                    <Typography variant="caption" color="textSecondary">Name</Typography>
                    <Typography variant="body2" className="font-medium">{userName}</Typography>
                  </Box>
                </Box>
              </Grid>
              <Grid item xs={12} sm={6}>
                <Box className="flex items-center space-x-2">
                  <Email className="text-blue-600" />
                  <Box>
                    <Typography variant="caption" color="textSecondary">Email</Typography>
                    <Typography variant="body2" className="font-medium">{userEmail}</Typography>
                  </Box>
                </Box>
              </Grid>
              <Grid item xs={12} sm={6}>
                <Box className="flex items-center space-x-2">
                  <Phone className="text-blue-600" />
                  <Box>
                    <Typography variant="caption" color="textSecondary">Phone</Typography>
                    <Typography variant="body2" className="font-medium">{userPhone}</Typography>
                  </Box>
                </Box>
              </Grid>
              <Grid item xs={12} sm={6}>
                <Box className="flex items-center space-x-2">
                  <Business className="text-blue-600" />
                  <Box>
                    <Typography variant="caption" color="textSecondary">Company</Typography>
                    <Typography variant="body2" className="font-medium">{userCompany}</Typography>
                  </Box>
                </Box>
              </Grid>
              <Grid item xs={12} sm={6}>
                <Box className="flex items-center space-x-2">
                  <Store className="text-blue-600" />
                  <Box>
                    <Typography variant="caption" color="textSecondary">MSE Type</Typography>
                    <Typography variant="body2" className="font-medium">{userMseType}</Typography>
                  </Box>
                </Box>
              </Grid>
            </Grid>
          </Paper>

          <form onSubmit={handleSubmit} className="space-y-4">
            <TextField
              fullWidth
              label="OTP Code"
              name="otp"
              value={formData.otp}
              onChange={handleChange}
              required
              placeholder="Enter 6-digit OTP"
              inputProps={{ maxLength: 6 }}
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <Lock className="text-gray-400" />
                  </InputAdornment>
                ),
              }}
            />

            {/* OTP Timer and Resend */}
            <Box className="flex justify-between items-center">
              <Box className="flex items-center space-x-2">
                <Timer className="text-gray-400" />
                <Typography variant="body2" color="textSecondary">
                  {timeLeft > 0 ? `Resend available in ${formatTime(timeLeft)}` : 'OTP expired'}
                </Typography>
              </Box>
              <Button
                variant="text"
                size="small"
                onClick={handleResendOTP}
                disabled={!canResend || resendLoading}
                className="text-blue-600"
              >
                {resendLoading ? (
                  <CircularProgress size={16} className="mr-2" />
                ) : null}
                Resend OTP
              </Button>
            </Box>

            <TextField
              fullWidth
              label="Set Password"
              name="password"
              type={showPassword ? 'text' : 'password'}
              value={formData.password}
              onChange={handleChange}
              required
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <Lock className="text-gray-400" />
                  </InputAdornment>
                ),
                endAdornment: (
                  <InputAdornment position="end">
                    <IconButton
                      onClick={() => setShowPassword(!showPassword)}
                      edge="end"
                    >
                      {showPassword ? <VisibilityOff /> : <Visibility />}
                    </IconButton>
                  </InputAdornment>
                ),
              }}
            />

            <TextField
              fullWidth
              label="Confirm Password"
              name="confirmPassword"
              type={showConfirmPassword ? 'text' : 'password'}
              value={formData.confirmPassword}
              onChange={handleChange}
              required
              InputProps={{
                startAdornment: (
                  <InputAdornment position="start">
                    <Lock className="text-gray-400" />
                  </InputAdornment>
                ),
                endAdornment: (
                  <InputAdornment position="end">
                    <IconButton
                      onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                      edge="end"
                    >
                      {showConfirmPassword ? <VisibilityOff /> : <Visibility />}
                    </IconButton>
                  </InputAdornment>
                ),
              }}
            />

            <Button
              type="submit"
              fullWidth
              variant="contained"
              size="large"
              disabled={loading}
              className="h-12 text-lg font-semibold mt-6"
            >
              {loading ? 'Activating Account...' : 'Activate Account'}
            </Button>
          </form>

          <div className="mt-6 text-center">
            <Typography variant="body2" color="textSecondary">
              Already have an account?{' '}
              <Button
                variant="text"
                onClick={() => navigate('/login')}
                className="text-blue-600 hover:text-blue-800 font-medium"
              >
                Sign in
              </Button>
            </Typography>
          </div>
        </Paper>
      </Box>
    </div>
  );
};

export default OTPVerification; 