import React, { useState } from 'react';
import {
  Box,
  Typography,
  Paper,
  TextField,
  Button,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Alert,
  Grid,
  Divider,
} from '@mui/material';
import {
  Business,
  Person,
  Phone,
  Email,
  LocationOn,
  Description,
  Save,
} from '@mui/icons-material';

const RegisterMSE: React.FC = () => {
  const [formData, setFormData] = useState<any>({
    businessName: '',
    ownerName: '',
    email: '',
    phone: '',
    category: '',
    registrationNumber: '',
    taxId: '',
    businessType: '',
    employees: '',
    annualRevenue: '',
    address: '',
    description: '',
  });
  const [success, setSuccess] = useState<string>('');
  const [error, setError] = useState<string>('');

  const categories = [
    'Input MSE',
    'Production MSE',
    'Output MSE',
  ];

  const businessTypes = [
    'Sole Proprietorship',
    'Partnership',
    'Limited Liability Company',
    'Corporation',
    'Cooperative',
  ];

  const handleChange = (e: any) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value,
    });
  };

  const handleSubmit = async (e: any) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    // Basic validation
    if (!formData.businessName || !formData.ownerName || !formData.email) {
      setError('Please fill in all required fields');
      return;
    }

    try {
      await new Promise(resolve => setTimeout(resolve, 1000));
      setSuccess('MSE registered successfully!');
      setFormData({
        businessName: '',
        ownerName: '',
        email: '',
        phone: '',
        category: '',
        registrationNumber: '',
        taxId: '',
        businessType: '',
        employees: '',
        annualRevenue: '',
        address: '',
        description: '',
      });
    } catch (err) {
      setError('Failed to register MSE');
    }
  };

  return (
    <Box className="space-y-6">
      <Box className="flex justify-between items-center">
        <Typography variant="h5" className="font-semibold text-gray-800">
          Register New MSE
        </Typography>
        <Button
          variant="contained"
          startIcon={<Business />}
          className="bg-blue-600 hover:bg-blue-700"
        >
          View All MSEs
        </Button>
      </Box>

      {error && <Alert severity="error">{error}</Alert>}
      {success && <Alert severity="success">{success}</Alert>}

      <Paper className="p-6">
        <form onSubmit={handleSubmit}>
          <Grid container spacing={3}>
            {/* Business Information */}
            <Grid item xs={12}>
              <Box className="flex items-center space-x-2 mb-4">
                <Business className="text-blue-600" />
                <Typography variant="h6" className="font-semibold">
                  Business Information
                </Typography>
              </Box>
            </Grid>

            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="Business Name"
                name="businessName"
                value={formData.businessName}
                onChange={handleChange}
                required
                InputProps={{
                  startAdornment: <Business className="text-gray-400 mr-2" />,
                }}
              />
            </Grid>

            <Grid item xs={12} md={6}>
              <FormControl fullWidth required>
                <InputLabel>MSE Category</InputLabel>
                <Select
                  name="category"
                  value={formData.category}
                  onChange={handleChange}
                  label="MSE Category"
                >
                  {categories.map((category) => (
                    <MenuItem key={category} value={category}>
                      {category}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>

            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="Registration Number"
                name="registrationNumber"
                value={formData.registrationNumber}
                onChange={handleChange}
                placeholder="e.g., MSE-2024-001"
              />
            </Grid>

            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="Tax ID"
                name="taxId"
                value={formData.taxId}
                onChange={handleChange}
                placeholder="e.g., TAX-123456789"
              />
            </Grid>

            <Grid item xs={12} md={6}>
              <FormControl fullWidth>
                <InputLabel>Business Type</InputLabel>
                <Select
                  name="businessType"
                  value={formData.businessType}
                  onChange={handleChange}
                  label="Business Type"
                >
                  {businessTypes.map((type) => (
                    <MenuItem key={type} value={type}>
                      {type}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>

            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="Number of Employees"
                name="employees"
                type="number"
                value={formData.employees}
                onChange={handleChange}
                placeholder="e.g., 25"
              />
            </Grid>

            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="Annual Revenue"
                name="annualRevenue"
                type="number"
                value={formData.annualRevenue}
                onChange={handleChange}
                placeholder="e.g., 500000"
                InputProps={{
                  startAdornment: '$',
                }}
              />
            </Grid>

            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Business Address"
                name="address"
                value={formData.address}
                onChange={handleChange}
                multiline
                rows={2}
                InputProps={{
                  startAdornment: <LocationOn className="text-gray-400 mr-2" />,
                }}
              />
            </Grid>

            <Grid item xs={12}>
              <Divider className="my-4" />
            </Grid>

            {/* Owner Information */}
            <Grid item xs={12}>
              <Box className="flex items-center space-x-2 mb-4">
                <Person className="text-green-600" />
                <Typography variant="h6" className="font-semibold">
                  Owner Information
                </Typography>
              </Box>
            </Grid>

            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="Owner Name"
                name="ownerName"
                value={formData.ownerName}
                onChange={handleChange}
                required
                InputProps={{
                  startAdornment: <Person className="text-gray-400 mr-2" />,
                }}
              />
            </Grid>

            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="Email Address"
                name="email"
                type="email"
                value={formData.email}
                onChange={handleChange}
                required
                InputProps={{
                  startAdornment: <Email className="text-gray-400 mr-2" />,
                }}
              />
            </Grid>

            <Grid item xs={12} md={6}>
              <TextField
                fullWidth
                label="Phone Number"
                name="phone"
                value={formData.phone}
                onChange={handleChange}
                InputProps={{
                  startAdornment: <Phone className="text-gray-400 mr-2" />,
                }}
              />
            </Grid>

            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Business Description"
                name="description"
                value={formData.description}
                onChange={handleChange}
                multiline
                rows={4}
                placeholder="Describe the business activities, products, and services..."
                InputProps={{
                  startAdornment: <Description className="text-gray-400 mr-2" />,
                }}
              />
            </Grid>

            <Grid item xs={12}>
              <Box className="flex justify-end space-x-2 pt-4">
                <Button
                  variant="outlined"
                  onClick={() => {
                    setFormData({
                      businessName: '',
                      ownerName: '',
                      email: '',
                      phone: '',
                      category: '',
                      registrationNumber: '',
                      taxId: '',
                      businessType: '',
                      employees: '',
                      annualRevenue: '',
                      address: '',
                      description: '',
                    });
                  }}
                >
                  Clear Form
                </Button>
                <Button
                  type="submit"
                  variant="contained"
                  startIcon={<Save />}
                  className="bg-blue-600 hover:bg-blue-700"
                >
                  Register MSE
                </Button>
              </Box>
            </Grid>
          </Grid>
        </form>
      </Paper>
    </Box>
  );
};

export default RegisterMSE; 
