import React, { useState } from 'react';
import {
  Box,
  Typography,
  Paper,
  TextField,
  Button,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Alert,
  Grid,
} from '@mui/material';
import {
  Security,
  Description,
  Save,
} from '@mui/icons-material';

const CreatePrivileges: React.FC = () => {
  const [formData, setFormData] = useState<{
    privilegeName: string;
    description: string;
    module: string;
    action: string;
    resource: string;
  }>({
    privilegeName: '',
    description: '',
    module: '',
    action: '',
    resource: '',
  });
  const [success, setSuccess] = useState<string>('');
  const [error, setError] = useState<string>('');

  const modules = [
    'Dashboard',
    'Users',
    'MSEs',
    'Markets',
    'Reports',
    'System',
  ];

  const actions = [
    'Create',
    'Read',
    'Update',
    'Delete',
    'View',
    'Export',
    'Import',
  ];

  const resources = [
    'All',
    'Own',
    'Department',
    'Organization',
  ];

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement> | any) => {
    const { name, value } = e.target;
    setFormData({
      ...formData,
      [name]: value,
    });
  };

  const generatePrivilegeName = () => {
    const { module, action, resource } = formData;
    if (module && action && resource) {
      return `${module.toLowerCase()}.${action.toLowerCase()}.${resource.toLowerCase()}`;
    }
    return '';
  };

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setError('');
    setSuccess('');

    if (!formData.module || !formData.action || !formData.resource) {
      setError('Please fill in all required fields');
      return;
    }

    try {
      await new Promise(resolve => setTimeout(resolve, 1000));
      setSuccess('Privilege created successfully!');
      setFormData({
        privilegeName: '',
        description: '',
        module: '',
        action: '',
        resource: '',
      });
    } catch (err) {
      setError('Failed to create privilege');
    }
  };

  const privilegeName = generatePrivilegeName();

  return (
    <Box className="space-y-6">
      <Box className="flex justify-between items-center">
        <Typography variant="h5" className="font-semibold text-gray-800">
          Create New Privilege
        </Typography>
        <Button
          variant="contained"
          startIcon={<Security />}
          className="bg-blue-600 hover:bg-blue-700"
        >
          View All Privileges
        </Button>
      </Box>

      {error && <Alert severity="error">{error}</Alert>}
      {success && <Alert severity="success">{success}</Alert>}

      <Grid container spacing={3}>
        {/* Form */}
        <Grid item xs={12} md={8}>
          <Paper className="p-6">
            <form onSubmit={handleSubmit}>
              <Grid container spacing={3}>
                <Grid item xs={12}>
                  <Box className="flex items-center space-x-2 mb-4">
                    <Security className="text-blue-600" />
                    <Typography variant="h6" className="font-semibold">
                      Privilege Information
                    </Typography>
                  </Box>
                </Grid>

                <Grid item xs={12} md={6}>
                  <FormControl fullWidth required>
                    <InputLabel>Module</InputLabel>
                    <Select
                      name="module"
                      value={formData.module}
                      onChange={handleChange}
                      label="Module"
                    >
                      {modules.map((module) => (
                        <MenuItem key={module} value={module}>
                          {module}
                        </MenuItem>
                      ))}
                    </Select>
                  </FormControl>
                </Grid>

                <Grid item xs={12} md={6}>
                  <FormControl fullWidth required>
                    <InputLabel>Action</InputLabel>
                    <Select
                      name="action"
                      value={formData.action}
                      onChange={handleChange}
                      label="Action"
                    >
                      {actions.map((action) => (
                        <MenuItem key={action} value={action}>
                          {action}
                        </MenuItem>
                      ))}
                    </Select>
                  </FormControl>
                </Grid>

                <Grid item xs={12} md={6}>
                  <FormControl fullWidth required>
                    <InputLabel>Resource Scope</InputLabel>
                    <Select
                      name="resource"
                      value={formData.resource}
                      onChange={handleChange}
                      label="Resource Scope"
                    >
                      {resources.map((resource) => (
                        <MenuItem key={resource} value={resource}>
                          {resource}
                        </MenuItem>
                      ))}
                    </Select>
                  </FormControl>
                </Grid>

                <Grid item xs={12} md={6}>
                  <TextField
                    fullWidth
                    label="Privilege Name"
                    value={privilegeName}
                    InputProps={{
                      readOnly: true,
                      startAdornment: <Security className="text-gray-400 mr-2" />,
                    }}
                    placeholder="Auto-generated"
                  />
                </Grid>

                <Grid item xs={12}>
                  <TextField
                    fullWidth
                    label="Description"
                    name="description"
                    value={formData.description}
                    onChange={handleChange}
                    multiline
                    rows={3}
                    placeholder="Describe what this privilege allows users to do..."
                    InputProps={{
                      startAdornment: <Description className="text-gray-400 mr-2" />,
                    }}
                  />
                </Grid>

                <Grid item xs={12}>
                  <Box className="flex justify-end space-x-2 pt-4">
                    <Button
                      variant="outlined"
                      onClick={() => {
                        setFormData({
                          privilegeName: '',
                          description: '',
                          module: '',
                          action: '',
                          resource: '',
                        });
                      }}
                    >
                      Clear Form
                    </Button>
                    <Button
                      type="submit"
                      variant="contained"
                      startIcon={<Save />}
                      className="bg-blue-600 hover:bg-blue-700"
                    >
                      Create Privilege
                    </Button>
                  </Box>
                </Grid>
              </Grid>
            </form>
          </Paper>
        </Grid>

        {/* Preview */}
        <Grid item xs={12} md={4}>
          <Paper className="p-6">
            <Typography variant="h6" className="font-semibold mb-4">
              Privilege Preview
            </Typography>
            
            <Box className="space-y-4">
              <Box>
                <Typography variant="body2" color="textSecondary">
                  Module
                </Typography>
                <Typography variant="body1" className="font-medium">
                  {formData.module || 'Not selected'}
                </Typography>
              </Box>

              <Box>
                <Typography variant="body2" color="textSecondary">
                  Action
                </Typography>
                <Typography variant="body1" className="font-medium">
                  {formData.action || 'Not selected'}
                </Typography>
              </Box>

              <Box>
                <Typography variant="body2" color="textSecondary">
                  Resource Scope
                </Typography>
                <Typography variant="body1" className="font-medium">
                  {formData.resource || 'Not selected'}
                </Typography>
              </Box>

              <Box>
                <Typography variant="body2" color="textSecondary">
                  Generated Name
                </Typography>
                <Typography variant="body1" className="font-medium font-mono text-blue-600">
                  {privilegeName || 'Not generated'}
                </Typography>
              </Box>

              <Box>
                <Typography variant="body2" color="textSecondary">
                  Description
                </Typography>
                <Typography variant="body1">
                  {formData.description || 'No description provided'}
                </Typography>
              </Box>
            </Box>
          </Paper>
        </Grid>
      </Grid>
    </Box>
  );
};

export default CreatePrivileges; 
