import React, { useState } from 'react';
import {
  Box,
  Typography,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  IconButton,
  Chip,
  TextField,
  InputAdornment,
  Button,
} from '@mui/material';
import {
  Search,
  Edit,
  Delete,
  Visibility,
  Add,
} from '@mui/icons-material';

const ListMSE: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState<string>('');
  const [filterCategory, setFilterCategory] = useState<string>('');

  // Mock data for MSEs
  const mses = [
    {
      id: 1,
      businessName: 'ABC Agricultural Supplies',
      ownerName: 'John Smith',
      category: 'Agricultural Inputs',
      email: 'john@abcagri.com',
      phone: '+1234567890',
      status: 'Active',
      employees: 15,
      annualRevenue: '$500,000',
    },
    {
      id: 2,
      businessName: 'Fresh Food Processors',
      ownerName: 'Jane Doe',
      category: 'Food Processing',
      email: 'jane@freshfood.com',
      phone: '+1234567891',
      status: 'Active',
      employees: 25,
      annualRevenue: '$750,000',
    },
    {
      id: 3,
      businessName: 'City Retail Store',
      ownerName: 'Mike Johnson',
      category: 'Retail Distribution',
      email: 'mike@cityretail.com',
      phone: '+1234567892',
      status: 'Active',
      employees: 8,
      annualRevenue: '$300,000',
    },
  ];

  const filteredMSEs = mses.filter(mse => {
    const matchesSearch = mse.businessName.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         mse.ownerName.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesCategory = !filterCategory || mse.category === filterCategory;
    return matchesSearch && matchesCategory;
  });

  const categories = Array.from(new Set(mses.map(m => m.category)));

  return (
    <Box className="space-y-6">
      <Box className="flex justify-between items-center">
        <Typography variant="h5" className="font-semibold text-gray-800">
          Registered MSEs
        </Typography>
        <Button
          variant="contained"
          startIcon={<Add />}
          className="bg-blue-600 hover:bg-blue-700"
        >
          Add MSE
        </Button>
      </Box>

      <Paper className="p-6">
        {/* Filters */}
        <Box className="flex gap-4 mb-6">
          <TextField
            placeholder="Search MSEs..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <Search />
                </InputAdornment>
              ),
            }}
            className="flex-1"
          />
          <TextField
            select
            label="Filter by Category"
            value={filterCategory}
            onChange={(e) => setFilterCategory(e.target.value)}
            className="w-48"
          >
            <option value="">All Categories</option>
            {categories.map((category) => (
              <option key={category} value={category}>
                {category}
              </option>
            ))}
          </TextField>
        </Box>

        {/* Table */}
        <TableContainer>
          <Table>
            <TableHead>
              <TableRow className="bg-gray-50">
                <TableCell className="font-semibold">Business Name</TableCell>
                <TableCell className="font-semibold">Owner</TableCell>
                <TableCell className="font-semibold">Category</TableCell>
                <TableCell className="font-semibold">Contact</TableCell>
                <TableCell className="font-semibold">Employees</TableCell>
                <TableCell className="font-semibold">Revenue</TableCell>
                <TableCell className="font-semibold">Status</TableCell>
                <TableCell className="font-semibold">Actions</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {filteredMSEs.map((mse) => (
                <TableRow key={mse.id} className="hover:bg-gray-50">
                  <TableCell>
                    <Typography variant="subtitle2" className="font-medium">
                      {mse.businessName}
                    </Typography>
                  </TableCell>
                  <TableCell>
                    <Typography variant="body2">
                      {mse.ownerName}
                    </Typography>
                  </TableCell>
                  <TableCell>
                    <Chip
                      label={mse.category}
                      size="small"
                      className="bg-blue-100 text-blue-800"
                    />
                  </TableCell>
                  <TableCell>
                    <Box>
                      <Typography variant="body2">{mse.email}</Typography>
                      <Typography variant="body2" color="textSecondary">
                        {mse.phone}
                      </Typography>
                    </Box>
                  </TableCell>
                  <TableCell>
                    <Chip
                      label={mse.employees}
                      size="small"
                      className="bg-green-100 text-green-800"
                    />
                  </TableCell>
                  <TableCell>
                    <Typography variant="body2" className="font-medium">
                      {mse.annualRevenue}
                    </Typography>
                  </TableCell>
                  <TableCell>
                    <Chip
                      label={mse.status}
                      size="small"
                      className={
                        mse.status === 'Active'
                          ? 'bg-green-100 text-green-800'
                          : 'bg-red-100 text-red-800'
                      }
                    />
                  </TableCell>
                  <TableCell>
                    <Box className="flex space-x-1">
                      <IconButton size="small" className="text-blue-600">
                        <Visibility fontSize="small" />
                      </IconButton>
                      <IconButton size="small" className="text-green-600">
                        <Edit fontSize="small" />
                      </IconButton>
                      <IconButton size="small" className="text-red-600">
                        <Delete fontSize="small" />
                      </IconButton>
                    </Box>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>

        {filteredMSEs.length === 0 && (
          <Box className="text-center py-8">
            <Typography variant="body1" color="textSecondary">
              No MSEs found matching your criteria
            </Typography>
          </Box>
        )}
      </Paper>
    </Box>
  );
};

export default ListMSE; 
