import React from 'react';
import { useAuth } from '../../context/AuthContext';
import InputMSEDashboard from './InputMSEDashboard';
import ProductionMSEDashboard from './ProductionMSEDashboard';
import OutputMSEDashboard from './OutputMSEDashboard';
import {
  Box,
  Grid,
  Paper,
  Typography,
  Card,
  CardContent,
  IconButton,
  Chip,
} from '@mui/material';
import {
  People,
  Business,
  Store,
  AttachMoney,
  MoreVert,
  ArrowUpward,
  ArrowDownward,
} from '@mui/icons-material';
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  PieChart,
  Pie,
  Cell,
} from 'recharts';

interface RevenueData {
  name: string;
  revenue: number;
  expenses: number;
}

interface MSEData {
  name: string;
  value: number;
  color: string;
}

interface StatsCard {
  title: string;
  value: string;
  change: string;
  positive: boolean;
  icon: React.ReactNode;
}

interface Transaction {
  id: number;
  type: string;
  amount: string;
  mse: string;
  date: string;
  status: string;
}

const Dashboard: React.FC = () => {
  const { user } = useAuth();

  // Route to specialized dashboard based on user role
  if (user?.role === 'Input MSE') {
    return <InputMSEDashboard />;
  }
  
  if (user?.role === 'Production MSE') {
    return <ProductionMSEDashboard />;
  }
  
  if (user?.role === 'Output MSE') {
    return <OutputMSEDashboard />;
  }

  // Default admin dashboard for other roles
  // Mock data for charts
  const revenueData: RevenueData[] = [
    { name: 'Jan', revenue: 4000, expenses: 2400 },
    { name: 'Feb', revenue: 3000, expenses: 1398 },
    { name: 'Mar', revenue: 2000, expenses: 9800 },
    { name: 'Apr', revenue: 2780, expenses: 3908 },
    { name: 'May', revenue: 1890, expenses: 4800 },
    { name: 'Jun', revenue: 2390, expenses: 3800 },
  ];

  const mseData: MSEData[] = [
    { name: 'Input MSE', value: 35, color: '#3B82F6' },
    { name: 'Production MSE', value: 25, color: '#10B981' },
    { name: 'Output MSE', value: 40, color: '#F59E0B' },
  ];

  const statsCards: StatsCard[] = [
    {
      title: 'Total Revenue',
      value: '$45,231',
      change: '+20.1%',
      positive: true,
      icon: <AttachMoney className="text-green-500" />,
    },
    {
      title: 'Active Users',
      value: '2,350',
      change: '+180.1%',
      positive: true,
      icon: <People className="text-blue-500" />,
    },
    {
      title: 'Registered MSEs',
      value: '1,234',
      change: '+19%',
      positive: true,
      icon: <Business className="text-purple-500" />,
    },
    {
      title: 'Market Transactions',
      value: '12,234',
      change: '-2.3%',
      positive: false,
      icon: <Store className="text-orange-500" />,
    },
  ];

  const recentTransactions: Transaction[] = [
    {
      id: 1,
      type: 'Purchase',
      amount: '$1,200',
      mse: 'ABC Production',
      date: '2024-01-15',
      status: 'completed',
    },
    {
      id: 2,
      type: 'Sale',
      amount: '$800',
      mse: 'XYZ Input',
      date: '2024-01-14',
      status: 'pending',
    },
    {
      id: 3,
      type: 'Purchase',
      amount: '$2,100',
      mse: 'DEF Output',
      date: '2024-01-13',
      status: 'completed',
    },
  ];

  return (
    <Box className="space-y-6">
      {/* Header */}
      <Box className="flex justify-between items-center">
        <Typography variant="h4" className="font-bold text-gray-800">
          Dashboard
        </Typography>
        <Chip
          label="Last 30 days"
          className="bg-blue-100 text-blue-800"
        />
      </Box>

      {/* Stats Cards */}
      <Grid container spacing={3} className="bg-background">
        {statsCards.map((card, index) => (
          <Grid item xs={12} sm={6} lg={3} key={index}>
            <Card className="h-full hover:shadow-lg transition-shadow">
              <CardContent>
                <Box className="flex justify-between items-start">
                  <Box>
                    <Typography color="textSecondary" gutterBottom>
                      {card.title}
                    </Typography>
                    <Typography variant="h4" className="font-bold text-text">
                      {card.value}
                    </Typography>
                    <Box className="flex items-center mt-2">
                      {card.positive ? (
                        <ArrowUpward className="text-green-500 text-sm mr-1" />
                      ) : (
                        <ArrowDownward className="text-red-500 text-sm mr-1" />
                      )}
                      <Typography
                        variant="body2"
                        className={card.positive ? 'text-green-500' : 'text-red-500'}
                      >
                        {card.change}
                      </Typography>
                    </Box>
                  </Box>
                  <Box className="p-2 bg-gray-50 rounded-lg">
                    {card.icon}
                  </Box>
                </Box>
              </CardContent>
            </Card>
          </Grid>
        ))}
      </Grid>

      {/* Charts Section */}
      <Grid container spacing={3}>
        {/* Revenue Chart */}
        <Grid item xs={12} lg={8}>
          <Paper className="p-6">
            <Box className="flex justify-between items-center mb-4">
              <Typography variant="h6" className="font-semibold">
                Revenue Overview
              </Typography>
              <IconButton size="small">
                <MoreVert />
              </IconButton>
            </Box>
            <ResponsiveContainer width="100%" height={300}>
              <LineChart data={revenueData}>
                <CartesianGrid strokeDasharray="3 3" />
                <XAxis dataKey="name" />
                <YAxis />
                <Tooltip />
                <Line
                  type="monotone"
                  dataKey="revenue"
                  stroke="#3B82F6"
                  strokeWidth={2}
                  name="Revenue"
                />
                <Line
                  type="monotone"
                  dataKey="expenses"
                  stroke="#EF4444"
                  strokeWidth={2}
                  name="Expenses"
                />
              </LineChart>
            </ResponsiveContainer>
          </Paper>
        </Grid>

        {/* MSE Distribution */}
        <Grid item xs={12} lg={4}>
          <Paper className="p-6">
            <Typography variant="h6" className="font-semibold mb-4">
              MSE Distribution
            </Typography>
            <ResponsiveContainer width="100%" height={300}>
              <PieChart>
                <Pie
                  data={mseData}
                  cx="50%"
                  cy="50%"
                  labelLine={false}
                  label={({ name, percent }) => `${name} ${(percent * 100).toFixed(0)}%`}
                  outerRadius={80}
                  fill="#8884d8"
                  dataKey="value"
                >
                  {mseData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={entry.color} />
                  ))}
                </Pie>
                <Tooltip />
              </PieChart>
            </ResponsiveContainer>
          </Paper>
        </Grid>
      </Grid>

      {/* Recent Transactions */}
      <Paper className="p-6">
        <Box className="flex justify-between items-center mb-4">
          <Typography variant="h6" className="font-semibold">
            Recent Transactions
          </Typography>
          <IconButton size="small">
            <MoreVert />
          </IconButton>
        </Box>
        <Box className="space-y-3">
          {recentTransactions.map((transaction) => (
            <Box
              key={transaction.id}
              className="flex justify-between items-center p-3 bg-gray-50 rounded-lg"
            >
              <Box>
                <Typography variant="subtitle2" className="font-medium">
                  {transaction.type}
                </Typography>
                <Typography variant="body2" color="textSecondary">
                  {transaction.mse}
                </Typography>
              </Box>
              <Box className="text-right">
                <Typography variant="subtitle2" className="font-medium">
                  {transaction.amount}
                </Typography>
                <Typography variant="body2" color="textSecondary">
                  {transaction.date}
                </Typography>
              </Box>
              <Chip
                label={transaction.status}
                size="small"
                className={
                  transaction.status === 'completed'
                    ? 'bg-green-100 text-green-800'
                    : 'bg-yellow-100 text-yellow-800'
                }
              />
            </Box>
          ))}
        </Box>
      </Paper>
    </Box>
  );
};

export default Dashboard; 