import React, { useState } from 'react';
import {
  Box,
  Typography,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  IconButton,
  Chip,
  Button,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  TextField,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Alert,
  Grid,
} from '@mui/material';
import {
  Add,
  ShoppingCart,
  Person,
  Business,
  AccountBalance,
  Visibility,
  Edit,
} from '@mui/icons-material';

const InputMSEs: React.FC = () => {
  const [openDialog, setOpenDialog] = useState<boolean>(false);
  const [dialogType, setDialogType] = useState<string>('');
  const [success, setSuccess] = useState<string>('');
  const [error, setError] = useState<string>('');

  // Mock data
  const customers = [
    {
      id: 1,
      name: 'John Smith',
      email: 'john@example.com',
      phone: '+1234567890',
      type: 'Individual',
      status: 'Active',
      totalPurchases: '$2,450',
    },
    {
      id: 2,
      name: 'ABC Farm',
      email: 'contact@abcfarm.com',
      phone: '+1234567891',
      type: 'Business',
      status: 'Active',
      totalPurchases: '$5,200',
    },
  ];

  const valueChains = [
    {
      id: 1,
      name: 'Agricultural Inputs Chain',
      description: 'Complete supply chain for agricultural inputs',
      participants: 15,
      status: 'Active',
    },
    {
      id: 2,
      name: 'Fertilizer Distribution',
      description: 'Fertilizer supply and distribution network',
      participants: 8,
      status: 'Active',
    },
  ];

  const products = [
    {
      id: 1,
      name: 'Organic Seeds',
      category: 'Seeds',
      price: '$25.00',
      stock: 150,
      supplier: 'ABC Seeds Co.',
      status: 'Available',
    },
    {
      id: 2,
      name: 'NPK Fertilizer',
      category: 'Fertilizers',
      price: '$45.00',
      stock: 75,
      supplier: 'Green Fertilizers',
      status: 'Available',
    },
  ];

  const purchases = [
    {
      id: 1,
      customer: 'John Smith',
      product: 'Organic Seeds',
      quantity: 5,
      amount: '$125.00',
      date: '2024-01-15',
      status: 'Completed',
    },
    {
      id: 2,
      customer: 'ABC Farm',
      product: 'NPK Fertilizer',
      quantity: 10,
      amount: '$450.00',
      date: '2024-01-14',
      status: 'Pending',
    },
  ];

  const handleOpenDialog = (type: string) => {
    setDialogType(type);
    setOpenDialog(true);
  };

  const handleCloseDialog = (): void => {
    setOpenDialog(false);
    setDialogType('');
  };

  const handleSubmit = async () => {
    setError('');
    setSuccess('');

    try {
      await new Promise(resolve => setTimeout(resolve, 1000));
      setSuccess(`${dialogType} created successfully!`);
      handleCloseDialog();
    } catch (err) {
      setError(`Failed to create ${dialogType.toLowerCase()}`);
    }
  };

  const renderDialogContent = () => {
    switch (dialogType) {
      case 'Customer':
        return (
          <Grid container spacing={2}>
            <Grid item xs={12} md={6}>
              <TextField fullWidth label="Name" name="name" required />
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField fullWidth label="Email" name="email" type="email" required />
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField fullWidth label="Phone" name="phone" required />
            </Grid>
            <Grid item xs={12} md={6}>
              <FormControl fullWidth>
                <InputLabel>Type</InputLabel>
                <Select name="type" label="Type">
                  <MenuItem value="Individual">Individual</MenuItem>
                  <MenuItem value="Business">Business</MenuItem>
                </Select>
              </FormControl>
            </Grid>
          </Grid>
        );
      case 'Value Chain':
        return (
          <Grid container spacing={2}>
            <Grid item xs={12}>
              <TextField fullWidth label="Chain Name" name="name" required />
            </Grid>
            <Grid item xs={12}>
              <TextField fullWidth label="Description" name="description" multiline rows={3} />
            </Grid>
          </Grid>
        );
      case 'Product':
        return (
          <Grid container spacing={2}>
            <Grid item xs={12} md={6}>
              <TextField fullWidth label="Product Name" name="name" required />
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField fullWidth label="Category" name="category" required />
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField fullWidth label="Price" name="price" type="number" required />
            </Grid>
            <Grid item xs={12} md={6}>
              <TextField fullWidth label="Stock Quantity" name="stock" type="number" required />
            </Grid>
            <Grid item xs={12}>
              <TextField fullWidth label="Supplier" name="supplier" required />
            </Grid>
          </Grid>
        );
      default:
        return null;
    }
  };

  return (
    <Box className="space-y-6">
      <Box className="flex justify-between items-center">
        <Typography variant="h5" className="font-semibold text-gray-800">
          Input MSEs Management
        </Typography>
        <Box className="flex space-x-2">
          <Button
            variant="outlined"
            startIcon={<Person />}
            onClick={() => handleOpenDialog('Customer')}
          >
            Register Customer
          </Button>
          <Button
            variant="outlined"
            startIcon={<Business />}
            onClick={() => handleOpenDialog('Value Chain')}
          >
            Register Value Chain
          </Button>
          <Button
            variant="outlined"
            startIcon={<ShoppingCart />}
            onClick={() => handleOpenDialog('Product')}
          >
            Register Product
          </Button>
        </Box>
      </Box>

      {error && <Alert severity="error">{error}</Alert>}
      {success && <Alert severity="success">{success}</Alert>}

      {/* Quick Actions */}
      <Grid container spacing={3}>
        <Grid item xs={12} sm={6} md={3}>
          <Paper className="p-4 text-center hover:shadow-lg transition-shadow cursor-pointer">
            <Person className="text-blue-600 text-3xl mb-2" />
            <Typography variant="h6">Customers</Typography>
            <Typography variant="body2" color="textSecondary">
              {customers.length} registered
            </Typography>
          </Paper>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Paper className="p-4 text-center hover:shadow-lg transition-shadow cursor-pointer">
            <Business className="text-green-600 text-3xl mb-2" />
            <Typography variant="h6">Value Chains</Typography>
            <Typography variant="body2" color="textSecondary">
              {valueChains.length} active
            </Typography>
          </Paper>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Paper className="p-4 text-center hover:shadow-lg transition-shadow cursor-pointer">
            <ShoppingCart className="text-purple-600 text-3xl mb-2" />
            <Typography variant="h6">Products</Typography>
            <Typography variant="body2" color="textSecondary">
              {products.length} available
            </Typography>
          </Paper>
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <Paper className="p-4 text-center hover:shadow-lg transition-shadow cursor-pointer">
            <AccountBalance className="text-orange-600 text-3xl mb-2" />
            <Typography variant="h6">Wallet</Typography>
            <Typography variant="body2" color="textSecondary">
              View balance
            </Typography>
          </Paper>
        </Grid>
      </Grid>

      {/* Recent Purchases */}
      <Paper className="p-6">
        <Box className="flex justify-between items-center mb-4">
          <Typography variant="h6" className="font-semibold">
            Recent Purchases
          </Typography>
          <Button
            variant="contained"
            startIcon={<Add />}
            className="bg-blue-600 hover:bg-blue-700"
          >
            New Purchase
          </Button>
        </Box>
        <TableContainer>
          <Table>
            <TableHead>
              <TableRow className="bg-gray-50">
                <TableCell className="font-semibold">Customer</TableCell>
                <TableCell className="font-semibold">Product</TableCell>
                <TableCell className="font-semibold">Quantity</TableCell>
                <TableCell className="font-semibold">Amount</TableCell>
                <TableCell className="font-semibold">Date</TableCell>
                <TableCell className="font-semibold">Status</TableCell>
                <TableCell className="font-semibold">Actions</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {purchases.map((purchase) => (
                <TableRow key={purchase.id} className="hover:bg-gray-50">
                  <TableCell>{purchase.customer}</TableCell>
                  <TableCell>{purchase.product}</TableCell>
                  <TableCell>{purchase.quantity}</TableCell>
                  <TableCell className="font-medium">{purchase.amount}</TableCell>
                  <TableCell>{purchase.date}</TableCell>
                  <TableCell>
                    <Chip
                      label={purchase.status}
                      size="small"
                      className={
                        purchase.status === 'Completed'
                          ? 'bg-green-100 text-green-800'
                          : 'bg-yellow-100 text-yellow-800'
                      }
                    />
                  </TableCell>
                  <TableCell>
                    <Box className="flex space-x-1">
                      <IconButton size="small" className="text-blue-600">
                        <Visibility fontSize="small" />
                      </IconButton>
                      <IconButton size="small" className="text-green-600">
                        <Edit fontSize="small" />
                      </IconButton>
                    </Box>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      </Paper>

      {/* Dialog */}
      <Dialog open={openDialog} onClose={handleCloseDialog} maxWidth="md" fullWidth>
        <DialogTitle>
          Register New {dialogType}
        </DialogTitle>
        <DialogContent>
          <Box className="pt-2">
            {renderDialogContent()}
          </Box>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseDialog}>Cancel</Button>
          <Button 
            onClick={handleSubmit} 
            variant="contained"
            className="bg-blue-600 hover:bg-blue-700"
          >
            Register
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default InputMSEs; 
