import React, { createContext, useContext, useState, ReactNode, useEffect } from 'react';
import { User, AuthContextType, RegisterFormData } from '../types';
import { api } from '../config/api';

const AuthContext = createContext<AuthContextType | undefined>(undefined);

interface AuthProviderProps {
  children: ReactNode;
}



export const AuthProvider: React.FC<AuthProviderProps> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState<boolean>(true);

    // Check for existing token on app load
  useEffect(() => {
    const initializeAuth = async () => {
      const token = localStorage.getItem('accessToken');
      if (token) {
        try {
          // Verify token is still valid by fetching user profile
          const response = await api.auth.getProfile();
          if (response.success && response.data) {
            setUser({
              ...response.data,
              name: response.data.full_name || response.data.name,
              role: response.data.role || 'Admin',
              mseType: response.data.mse_type || 'Input MSE',
              mseCode: response.data.mse_code || 'MSE001'
            });
          } else {
            // Token is invalid, clear it
            localStorage.removeItem('accessToken');
            localStorage.removeItem('refreshToken');
          }
        } catch (error) {
          console.error('Token validation failed:', error);
          // Clear invalid tokens
          localStorage.removeItem('accessToken');
          localStorage.removeItem('refreshToken');
        }
      }
      setLoading(false);
    };

    initializeAuth();
  }, []);

  const login = async (email: string, password: string): Promise<void> => {
    setLoading(true);
    try {
      // Real API login
      const response = await api.auth.login({ email, password });
      
      // Handle different response formats from backend
      if (response.success && response.data) {
        // Format: { success: true, data: { user, tokens } }
        const { user, tokens } = response.data;
        localStorage.setItem('accessToken', tokens.access);
        localStorage.setItem('refreshToken', tokens.refresh);
        
        setUser({
          ...user,
          name: user.full_name || user.name,
          role: user.role || 'Admin',
          mseType: user.mse_type || 'Input MSE',
          mseCode: user.mse_code || 'MSE001'
        });
      } else if (response.message === 'Login successful' && response.tokens) {
        // Format: { message: 'Login successful', user, tokens }
        localStorage.setItem('accessToken', response.tokens.access);
        localStorage.setItem('refreshToken', response.tokens.refresh);
        
        setUser({
          ...response.user,
          name: response.user.full_name || response.user.name,
          role: response.user.role || 'Admin',
          mseType: response.user.mse_type || 'Input MSE',
          mseCode: response.user.mse_code || 'MSE001'
        });
      } else if (response.access) {
        // Format: { access: token, user: {...} }
        localStorage.setItem('accessToken', response.access);
        if (response.refresh) {
          localStorage.setItem('refreshToken', response.refresh);
        }
        
        setUser({
          ...response.user,
          name: response.user.full_name || response.user.name,
          role: response.user.role || 'Admin',
          mseType: response.user.mse_type || 'Input MSE',
          mseCode: response.user.mse_code || 'MSE001'
        });
      } else {
        throw new Error(response.message || response.error || 'Login failed');
      }
    } catch (error) {
      console.error('Login failed:', error);
      throw error;
    } finally {
      setLoading(false);
    }
  };

  const logout = async (): Promise<void> => {
    try {
      await api.auth.logout();
    } catch (error) {
      console.error('Logout API call failed:', error);
    } finally {
      // Clear token and user data regardless of API call success
      localStorage.removeItem('accessToken');
      localStorage.removeItem('refreshToken');
      setUser(null);
    }
  };

  const register = async (userData: RegisterFormData): Promise<void> => {
    setLoading(true);
    try {
      const response = await api.auth.register(userData);
      
      // Backend returns: { message, user, tokens } on successful registration
      if (response.message !== 'User registered successfully') {
        throw new Error(response.message || 'Registration failed');
      }
      
      // Registration successful - user will need to wait for admin approval
      console.log('Registration submitted successfully:', response.user);
    } catch (error) {
      console.error('Registration failed:', error);
      throw error;
    } finally {
      setLoading(false);
    }
  };

  const value: AuthContextType = {
    user,
    isAuthenticated: !!user,
    loading,
    login,
    logout,
    register
  };

  return (
    <AuthContext.Provider value={value}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = (): AuthContextType => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}; 